// ─────────────────────────────────────────────────────────────────────────────
// Input is polled, never event-driven in the simulation. A short-lived
// `pressed` set gives us one-shot actions (jump, reload) without losing inputs
// between fixed physics steps.
// ─────────────────────────────────────────────────────────────────────────────
export class Input {
  constructor(canvas) {
    this.canvas = canvas;
    this.keys = new Set();
    this.pressed = new Set();
    this.lookX = 0;
    this.lookY = 0;
    this.fireHeld = false;
    this.firePressed = false;
    this.locked = false;
    this.enabled = false;
    this.touch = isTouchDevice();
    this.stick = { x: 0, y: 0 };
    this.touchActions = { sprint: false, slide: false, jump: false, fire: false };
    this.onLockChange = null;
    this.onFirstInteraction = null;

    this._bindKeyboard();
    this._bindMouse();
    if (this.touch) this._bindTouch();
  }

  _bindKeyboard() {
    addEventListener('keydown', (e) => {
      if (['Space', 'ShiftLeft', 'ControlLeft', 'KeyW', 'KeyA', 'KeyS', 'KeyD', 'Tab'].includes(e.code)) {
        e.preventDefault();
      }
      if (!e.repeat) {
        this.pressed.add(e.code);
        if (this.onFirstInteraction) this.onFirstInteraction();
      }
      this.keys.add(e.code);
    }, { passive: false });

    addEventListener('keyup', (e) => this.keys.delete(e.code));

    addEventListener('blur', () => {
      this.keys.clear();
      this.fireHeld = false;
      this.lookX = this.lookY = 0;
    });
  }

  _bindMouse() {
    this.canvas.addEventListener('mousedown', (e) => {
      if (!this.enabled) return;
      if (e.button === 0) {
        this.fireHeld = true;
        this.firePressed = true;
        if (!this.locked && !this.touch) this.requestLock();
      }
      if (this.onFirstInteraction) this.onFirstInteraction();
    });

    addEventListener('mouseup', (e) => {
      if (e.button === 0) this.fireHeld = false;
    });

    addEventListener('contextmenu', (e) => e.preventDefault());

    addEventListener('mousemove', (e) => {
      if (!this.locked || !this.enabled) return;
      // Clamp insane high-DPI spikes so one frame can never snap the camera.
      this.lookX += Math.max(-160, Math.min(160, e.movementX));
      this.lookY += Math.max(-160, Math.min(160, e.movementY));
    });

    document.addEventListener('pointerlockchange', () => {
      this.locked = document.pointerLockElement === this.canvas;
      if (this.onLockChange) this.onLockChange(this.locked);
    });
  }

  _bindTouch() {
    const stickBase = document.getElementById('stickBase');
    const stickKnob = document.getElementById('stickKnob');
    const bindHold = (id, key) => {
      const el = document.getElementById(id);
      if (!el) return;
      const down = (e) => {
        e.preventDefault();
        e.stopPropagation();
        this.touchActions[key] = true;
        if (key === 'jump') this.pressed.add('Space');
        if (key === 'fire') { this.firePressed = true; this.fireHeld = true; }
        el.classList.add('is-down');
        el.setPointerCapture?.(e.pointerId);
        this.onFirstInteraction?.();
      };
      const up = (e) => {
        e.preventDefault();
        e.stopPropagation();
        this.touchActions[key] = false;
        if (key === 'fire') this.fireHeld = false;
        el.classList.remove('is-down');
      };
      el.addEventListener('pointerdown', down);
      el.addEventListener('pointerup', up);
      el.addEventListener('pointercancel', up);
      el.addEventListener('lostpointercapture', up);
    };

    bindHold('touchSprint', 'sprint');
    bindHold('touchSlide', 'slide');
    bindHold('touchJump', 'jump');
    bindHold('touchFire', 'fire');

    // Touch stick: a fixed base is more reliable than a floating joystick.
    let stickPointer = null;
    const moveStick = (e) => {
      const rect = stickBase.getBoundingClientRect();
      const cx = rect.left + rect.width / 2;
      const cy = rect.top + rect.height / 2;
      const max = rect.width * 0.34;
      let dx = e.clientX - cx;
      let dy = e.clientY - cy;
      const len = Math.hypot(dx, dy) || 1;
      const scale = Math.min(1, max / len);
      dx *= scale; dy *= scale;
      this.stick.x = dx / max;
      this.stick.y = -dy / max;
      stickKnob.style.transform = `translate(calc(-50% + ${dx}px), calc(-50% + ${dy}px))`;
    };
    const endStick = (e) => {
      if (stickPointer !== e.pointerId) return;
      stickPointer = null;
      this.stick.x = this.stick.y = 0;
      stickKnob.style.transform = 'translate(-50%,-50%)';
    };
    stickBase.addEventListener('pointerdown', (e) => {
      e.preventDefault();
      e.stopPropagation();
      stickPointer = e.pointerId;
      stickBase.setPointerCapture?.(e.pointerId);
      moveStick(e);
      this.onFirstInteraction?.();
    });
    stickBase.addEventListener('pointermove', (e) => {
      if (e.pointerId === stickPointer) { e.preventDefault(); moveStick(e); }
    });
    stickBase.addEventListener('pointerup', endStick);
    stickBase.addEventListener('pointercancel', endStick);

    // Look drag on the canvas. It ignores controls because they stopPropagation.
    let lookPointer = null;
    let lastX = 0, lastY = 0;
    this.canvas.addEventListener('pointerdown', (e) => {
      if (!this.enabled) return;
      lookPointer = e.pointerId;
      lastX = e.clientX; lastY = e.clientY;
      this.canvas.setPointerCapture?.(e.pointerId);
    });
    this.canvas.addEventListener('pointermove', (e) => {
      if (e.pointerId !== lookPointer || !this.enabled) return;
      this.lookX += (e.clientX - lastX) * 1.5;
      this.lookY += (e.clientY - lastY) * 1.5;
      lastX = e.clientX; lastY = e.clientY;
    });
    const endLook = (e) => { if (e.pointerId === lookPointer) lookPointer = null; };
    this.canvas.addEventListener('pointerup', endLook);
    this.canvas.addEventListener('pointercancel', endLook);
  }

  requestLock() {
    if (this.touch || !this.enabled) return;
    try {
      const promise = this.canvas.requestPointerLock({ unadjustedMovement: true });
      promise?.catch?.(() => this.canvas.requestPointerLock());
    } catch {
      this.canvas.requestPointerLock?.();
    }
  }

  get moveX() {
    let x = 0;
    if (this.keys.has('KeyD')) x += 1;
    if (this.keys.has('KeyA')) x -= 1;
    if (this.touch) x += this.stick.x;
    return Math.max(-1, Math.min(1, x));
  }

  get moveY() {
    let y = 0;
    if (this.keys.has('KeyW')) y += 1;
    if (this.keys.has('KeyS')) y -= 1;
    if (this.touch) y += this.stick.y;
    return Math.max(-1, Math.min(1, y));
  }

  get sprintHeld() {
    return this.keys.has('ShiftLeft') || this.keys.has('ShiftRight') || this.touchActions.sprint ||
      (this.touch && this.stick.y > 0.86);
  }

  get crouchHeld() {
    return this.keys.has('ControlLeft') || this.keys.has('ControlRight') ||
      this.keys.has('KeyC') || this.touchActions.slide;
  }

  get jumpHeld() {
    return this.keys.has('Space') || this.touchActions.jump;
  }

  get reloadPressed() { return this.pressed.has('KeyR'); }
  get jumpPressed() { return this.pressed.has('Space'); }

  consumeLook(out) {
    out.x = this.lookX;
    out.y = this.lookY;
    this.lookX = 0;
    this.lookY = 0;
    return out;
  }

  endFrame() {
    this.pressed.clear();
    this.firePressed = false;
  }
}

import * as THREE from 'three';
import { CONFIG as C } from './config.js';

const _forward = new THREE.Vector3();
const _wish = new THREE.Vector3();
const _tmp = new THREE.Vector3();

const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const damp = (a, b, rate, dt) => a + (b - a) * (1 - Math.exp(-rate * dt));
const easeOutCubic = (t) => 1 - Math.pow(1 - t, 3);
const easeInOutCubic = (t) => t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;

// ─────────────────────────────────────────────────────────────────────────────
// PlayerController
// Custom capsule-ish character controller. The world is a compact set of AABB
// colliders, which keeps collision queries branch-light and deterministic.
//
// Core rules:
//  • Ground movement: friction + very high acceleration.
//  • Slide: speed is preserved and steered toward the camera; no duration cap.
//  • Air: Quake-style acceleration adds momentum, never removes it.
//  • Jump: landing while jump is held auto-bhops with full horizontal speed.
//  • Mantle: a short, automatic vault over ledges in front of the player.
// ─────────────────────────────────────────────────────────────────────────────
export class PlayerController {
  constructor(camera, world) {
    this.camera = camera;
    this.world = world;

    this.position = new THREE.Vector3(C.arena.spawn.x, C.arena.spawn.y, C.arena.spawn.z);
    this.velocity = new THREE.Vector3();
    this.yaw = 0;
    this.pitch = 0;

    this.radius = C.player.radius;
    this.standingHeight = C.player.standingHeight;
    this.height = this.standingHeight;
    this.grounded = true;
    this.sliding = false;
    this.crouching = false;
    this.sprinting = false;
    this.mantling = false;
    this.airborne = false;

    this.eyeHeight = C.player.eyeStanding;
    this.eyeTarget = this.eyeHeight;
    this.bobPhase = 0;
    this.bobOffset = 0;
    this.bobX = 0;
    this.landDip = 0;
    this.landSpring = 0;
    this.slideRoll = 0;
    this.strafeRoll = 0;
    this.fov = C.camera.baseFov;
    this.speed = 0;
    this.horizontalSpeed = 0;
    this.airTime = 0;
    this.groundTime = 0;
    this.coyote = 0;
    this.jumpBuffer = 0;
    this.mantleCooldown = 0;
    this.lastGrounded = true;
    this.wasSliding = false;
    this.bhopChain = 0;
    this.slideTime = 0;
    this.events = [];

    this._mantle = null;
    this._wallHit = null;
    this._prevPosition = this.position.clone();
    this._slideDir = new THREE.Vector2(0, -1);
    this._baseYaw = this.yaw;
  }

  reset() {
    this.position.set(C.arena.spawn.x, C.arena.spawn.y, C.arena.spawn.z);
    this.velocity.set(0, 0, 0);
    this.yaw = 0; this.pitch = 0;
    this.grounded = true; this.sliding = false; this.crouching = false;
    this.mantling = false; this.airborne = false; this.speed = 0;
    this.eyeHeight = C.player.eyeStanding;
    this._mantle = null;
  }

  emit(name, data = null) {
    this.events.push({ name, data });
  }

  addLook(dx, dy) {
    this.yaw -= dx * C.camera.mouseSensitivity;
    this.pitch -= dy * C.camera.mouseSensitivity;
    this.pitch = clamp(this.pitch, -C.camera.pitchLimit, C.camera.pitchLimit);
    // Keep yaw bounded to avoid precision loss after very long sessions.
    if (this.yaw > Math.PI) this.yaw -= Math.PI * 2;
    if (this.yaw < -Math.PI) this.yaw += Math.PI * 2;
  }

  get forward() {
    _forward.set(-Math.sin(this.yaw), 0, -Math.cos(this.yaw));
    return _forward;
  }

  get speedRatio() {
    return clamp((this.horizontalSpeed - 4) / (C.movement.sprintSpeed - 4), 0, 1.35);
  }

  // ── Core step, called at a fixed 120 Hz ─────────────────────────────────────
  update(dt, input) {
    this._prevPosition.copy(this.position);
    this.lastGrounded = this.grounded;
    this.justLanded = false;
    this.mantleCooldown = Math.max(0, this.mantleCooldown - dt);
    this.jumpBuffer = Math.max(0, this.jumpBuffer - dt);

    if (this.mantling) {
      this._updateMantle(dt);
      this._updateCamera(dt);
      return;
    }

    if (input.jumpPressed) this.jumpBuffer = C.movement.jumpBufferTime;
    const wish = this._wishDirection(input);
    const wishLen = Math.hypot(wish.x, wish.z);

    // Crouch / slide intent. Entry is automatic while carrying speed.
    this._updateCrouchState(input);

    // ── Jump / bunny hop ─────────────────────────────────────────────────────
    const canJump = this.grounded || this.coyote > 0;
    if ((this.jumpBuffer > 0 || (input.jumpHeld && this.grounded)) && canJump) {
      if (!this._tryMantle(input, true)) {
        this._jump(input);
      }
      this.jumpBuffer = 0;
    }

    // ── Horizontal locomotion ───────────────────────────────────────────────
    if (this.sliding && this.grounded) {
      this._updateSlide(dt, input);
    } else if (this.grounded) {
      this._updateGround(dt, wish, wishLen, input);
    } else {
      this._updateAir(dt, wish, wishLen);
    }

    // ── Integrate + collide ─────────────────────────────────────────────────
    this._moveHorizontal(this.velocity.x * dt, this.velocity.z * dt);
    this._moveVertical(dt);

    // Mantle can trigger mid-air when the player carries momentum into a ledge.
    if (!this.grounded && !this.mantling && this.mantleCooldown <= 0 && this.airTime > 0.05) {
      const intoLedge = this._wallHit && this.forward.dot(_tmp.set(this.velocity.x, 0, this.velocity.z).normalize()) > 0.3;
      if (intoledgeGuard(this.velocity, this.forward) || intoLedge) {
        this._tryMantle(input, false);
      }
    }

    this._updateTimers(dt);
    this._updateCamera(dt);

    this.horizontalSpeed = Math.hypot(this.velocity.x, this.velocity.z);
    this.speed = this.horizontalSpeed;
    if (this.horizontalSpeed > C.movement.sprintSpeed + 0.5 && !this.sliding) this.bhopChain = Math.max(this.bhopChain, 1);
  }

  _updateTimers(dt) {
    if (this.grounded) {
      this.airTime = 0;
      this.groundTime += dt;
      this.coyote = C.movement.coyoteTime;
      if (this.sliding) this.slideTime += dt;
    } else {
      this.airTime += dt;
      this.groundTime = 0;
      this.coyote = Math.max(0, this.coyote - dt);
    }
    this.airborne = !this.grounded && !this.mantling;
  }

  _wishDirection(input) {
    const f = this.forward;
    _wish.set(
      f.x * input.moveY - f.z * input.moveX,
      0,
      f.z * input.moveY + f.x * input.moveX
    );
    const len = _wish.length();
    if (len > 1) _wish.multiplyScalar(1 / len);
    return _wish;
  }

  _updateCrouchState(input) {
    const wantsCrouch = input.crouchHeld;
    const speed = Math.hypot(this.velocity.x, this.velocity.z);

    if (wantsCrouch && !this.sliding && this.grounded && speed >= C.slide.minEntrySpeed) {
      this._startSlide(speed);
    }

    if (wantsCrouch && !this.sliding) {
      this.crouching = true;
      this.height = C.player.crouchHeight;
    }

    if (!wantsCrouch && this.sliding) {
      if (this._canStand()) {
        this.sliding = false;
        this.crouching = false;
        this.height = this.standingHeight;
        this.emit('slideEnd');
      }
    }

    if (!wantsCrouch && !this.sliding && this.crouching) {
      if (this._canStand()) {
        this.crouching = false;
        this.height = this.standingHeight;
      }
    }

    if (this.sliding) {
      this.crouching = true;
      this.height = C.player.crouchHeight;
    }
  }

  _startSlide(speed) {
    this.sliding = true;
    this.crouching = true;
    this.height = C.player.crouchHeight;
    this.slideTime = 0;
    this.wasSliding = true;
    const dir = new THREE.Vector2(this.velocity.x, this.velocity.z);
    if (dir.lengthSq() < 0.01) dir.set(-Math.sin(this.yaw), -Math.cos(this.yaw));
    dir.normalize();
    this._slideDir.copy(dir);
    const boosted = Math.min(C.slide.maxSpeed, speed * C.slide.entryBoost);
    this.velocity.x = dir.x * boosted;
    this.velocity.z = dir.y * boosted;
    this.emit('slideStart', boosted);
  }

  _updateSlide(dt, input) {
    const speed = Math.hypot(this.velocity.x, this.velocity.z);
    if (speed < 1.2) {
      this.sliding = false;
      this.crouching = input.crouchHeld;
      this.height = this.crouching ? C.player.crouchHeight : this.standingHeight;
      return;
    }

    // The slide has no duration timer. It only bleeds an almost imperceptible
    // amount of speed so a good line still feels like it stores momentum.
    let newSpeed = Math.min(C.slide.maxSpeed, speed * (1 - C.slide.drag * dt));

    // Steer the velocity vector, not the camera. A 180° look becomes a 180°
    // velocity turn at a fixed angular rate while speed stays constant.
    this._slideDir.set(this.velocity.x / speed, this.velocity.z / speed);
    const f = this.forward;
    const targetAngle = Math.atan2(f.x, f.z) + input.moveX * 0.38;
    const currentAngle = Math.atan2(this._slideDir.x, this._slideDir.y);
    let delta = targetAngle - currentAngle;
    while (delta > Math.PI) delta -= Math.PI * 2;
    while (delta < -Math.PI) delta += Math.PI * 2;
    const turn = clamp(delta, -C.slide.turnRate * dt, C.slide.turnRate * dt);
    const newAngle = currentAngle + turn;
    this._slideDir.set(Math.sin(newAngle), Math.cos(newAngle));

    this.velocity.x = this._slideDir.x * newSpeed;
    this.velocity.z = this._slideDir.y * newSpeed;
    this._slideTurn = turn / Math.max(dt, 0.0001);
  }

  _updateGround(dt, wish, wishLen, input) {
    const speed = Math.hypot(this.velocity.x, this.velocity.z);
    const crouching = this.crouching || this.sliding;
    this.sprinting = !crouching && input.sprintHeld && input.moveY > 0.15;

    // Ground friction: high enough to feel snappy, low enough to preserve a
    // post-slide flow state.
    if (speed > 0) {
      const drop = Math.max(speed, C.movement.stopSpeed) * C.movement.groundFriction * dt;
      const newSpeed = Math.max(0, speed - drop) / speed;
      this.velocity.x *= newSpeed;
      this.velocity.z *= newSpeed;
    }

    const targetSpeed = crouching ? 4.2 : (this.sprinting ? C.movement.sprintSpeed : C.movement.walkSpeed);
    this._accelerate(wish, wishLen, targetSpeed, C.movement.groundAcceleration, dt);
  }

  _updateAir(dt, wish, wishLen) {
    this.crouching = false;
    this.sprinting = false;
    this.height = this.standingHeight;

    // Quake air acceleration. The projection means holding a strafe key can
    // bend the trajectory and even gain a little speed, but never scrubs it.
    if (wishLen > 0.01) {
      const projected = this.velocity.x * wish.x + this.velocity.z * wish.z;
      const add = C.movement.airWishSpeed - projected;
      if (add > 0) {
        const accel = Math.min(C.movement.airAcceleration * dt, add);
        this.velocity.x += wish.x * accel;
        this.velocity.z += wish.z * accel;
      } else {
        // At high speed, nudge the vector toward the input without changing
        // magnitude. This is the "no deceleration" part of the brief.
        const vx = this.velocity.x, vz = this.velocity.z;
        const speed = Math.hypot(vx, vz);
        if (speed > 1) {
          const steer = Math.min(1, dt * C.movement.airSteerRate);
          let nx = vx / speed + wish.x * steer * 0.14;
          let nz = vz / speed + wish.z * steer * 0.14;
          const nl = Math.hypot(nx, nz) || 1;
          nx /= nl; nz /= nl;
          this.velocity.x = nx * speed;
          this.velocity.z = nz * speed;
        }
      }
    }

    // Preserve the boost, but prevent runaway acceleration.
    const hs = Math.hypot(this.velocity.x, this.velocity.z);
    if (hs > C.movement.maxAirSpeed) {
      const s = C.movement.maxAirSpeed / hs;
      this.velocity.x *= s;
      this.velocity.z *= s;
    }
  }

  _accelerate(wish, wishLen, targetSpeed, accel, dt) {
    if (wishLen < 0.01) return;
    const projected = this.velocity.x * wish.x + this.velocity.z * wish.z;
    const add = targetSpeed - projected;
    if (add <= 0) return;
    const amount = Math.min(accel * dt, add);
    this.velocity.x += wish.x * amount;
    this.velocity.z += wish.z * amount;
  }

  _jump(input) {
    const wasSliding = this.sliding;
    const slideSpeed = Math.hypot(this.velocity.x, this.velocity.z);
    this.velocity.y = C.movement.jumpSpeed;
    if (wasSliding && slideSpeed > 0) {
      // Slide-jump keeps almost all momentum and adds a tiny exit boost.
      const s = Math.min(C.slide.maxSpeed, slideSpeed * C.slide.jumpBoost) / slideSpeed;
      this.velocity.x *= s;
      this.velocity.z *= s;
    }
    this.sliding = false;
    this.crouching = false;
    this.height = this.standingHeight;
    this.grounded = false;
    this.coyote = 0;
    this.justLanded = false;
    this.emit(wasSliding ? 'slideJump' : 'jump', slideSpeed);
  }

  _updateVertical(dt) {
    if (this.grounded) {
      // Snap to steps and ramps while staying glued to the floor.
      const support = this._groundHeight(this.position.x, this.position.z, this.position.y + C.player.stepHeight + 0.08);
      if (support > -Infinity && this.position.y - support <= 0.48 && support <= this.position.y + C.player.stepHeight + 0.02) {
        this.position.y = support;
        this.velocity.y = 0;
      } else if (support > -Infinity && this.position.y - support > 0.49) {
        this.grounded = false;
      }
      if (this.grounded) return;
    }

    const oldY = this.position.y;
    this.velocity.y -= C.movement.gravity * dt;
    this.position.y += this.velocity.y * dt;

    const support = this._groundHeight(this.position.x, this.position.z, oldY + 0.04);
    if (this.velocity.y <= 0 && this.position.y <= support) {
      const impact = Math.abs(this.velocity.y);
      this.position.y = support;
      this.velocity.y = 0;
      this.grounded = true;
      this.justLanded = true;
      this.landDip = Math.min(0.13, impact * 0.009);
      this.landSpring = impact;
      this.emit('land', impact);

      // Auto-bhop: hold jump and the next physics step immediately launches.
      if (this.jumpBuffer > 0 || (this.grounded && this._jumpHeld)) {
        this.jumpBuffer = 0;
        this._bhopRequested = true;
      }
    } else {
      this.grounded = false;

      // Ceiling collision. Handles the low container underpass.
      const head = this.position.y + this.height;
      for (const { box } of this.world.colliders) {
        if (!this._circleOverlap(box, this.position.x, this.position.z, this.radius * 0.9)) continue;
        if (box.min.y < head && box.min.y >= oldY + this.height - 0.05) {
          if (this.velocity.y > 0) {
            this.position.y = box.min.y - this.height;
            this.velocity.y = 0;
          }
        }
      }
    }
  }

  _moveVertical(dt) {
    // Jump requests coming from the landing branch or the held-jump bhop.
    if (this._bhopRequested) {
      this._bhopRequested = false;
      if (!this._tryMantle(null, false)) this._jump(null);
    }
    this._updateVertical(dt);
  }

  _moveHorizontal(dx, dz) {
    this._wallHit = null;
    this.position.x += dx;
    this._resolveAxis('x', dx);
    this.position.z += dz;
    this._resolveAxis('z', dz);

    const limit = C.arena.halfSize - 0.7;
    this.position.x = clamp(this.position.x, -limit, limit);
    this.position.z = clamp(this.position.z, -limit, limit);
  }

  _resolveAxis(axis, delta) {
    if (Math.abs(delta) < 0.00001) return;
    const r = this.radius;
    for (const { box } of this.world.colliders) {
      if (!this._blocksPlayer(box)) continue;
      if (!this._circleOverlap(box, this.position.x, this.position.z, r)) continue;

      if (axis === 'x') {
        const center = (box.min.x + box.max.x) * 0.5;
        if (this.position.x > center) this.position.x = box.max.x + r + 0.001;
        else this.position.x = box.min.x - r - 0.001;
        this.velocity.x = 0;
      } else {
        const center = (box.min.z + box.max.z) * 0.5;
        if (this.position.z > center) this.position.z = box.max.z + r + 0.001;
        else this.position.z = box.min.z - r - 0.001;
        this.velocity.z = 0;
      }
      this._wallHit = box;
    }
  }

  _blocksPlayer(box) {
    return box.max.y > this.position.y + C.player.stepHeight + 0.015 &&
      box.min.y < this.position.y + this.height - 0.018;
  }

  _circleOverlap(box, x, z, r) {
    const cx = clamp(x, box.min.x, box.max.x);
    const cz = clamp(z, box.min.z, box.max.z);
    const dx = x - cx, dz = z - cz;
    return dx * dx + dz * dz < r * r;
  }

  _groundHeight(x, z, maxY) {
    let best = 0; // world floor
    for (const { box } of this.world.colliders) {
      if (!this._circleOverlap(box, x, z, this.radius * 0.72)) continue;
      const top = box.max.y;
      if (top <= maxY + 0.001 && top > best) best = top;
    }
    return best;
  }

  _canStand() {
    const target = this.position.y + this.standingHeight - 0.02;
    for (const { box } of this.world.colliders) {
      if (box.min.y >= target) continue;
      if (box.max.y <= this.position.y + C.player.stepHeight) continue;
      if (this._circleOverlap(box, this.position.x, this.position.z, this.radius * 0.8)) return false;
    }
    return true;
  }

  // ── Mantling ────────────────────────────────────────────────────────────────
  _tryMantle(input, fromJump) {
    if (this.mantleCooldown > 0 || this.mantling) return false;
    if (!fromJump && this.airTime < 0.04) return false;
    const ledge = this._findLedge();
    if (!ledge) return false;

    const speed = Math.hypot(this.velocity.x, this.velocity.z);
    this._mantle = {
      t: 0,
      duration: C.mantle.duration,
      start: this.position.clone(),
      end: new THREE.Vector3(ledge.x, ledge.top + 0.01, ledge.z),
      speed,
      dirX: ledge.dirX,
      dirZ: ledge.dirZ,
    };
    this.mantling = true;
    this.grounded = false;
    this.sliding = false;
    this.crouching = false;
    this.height = this.standingHeight;
    this.velocity.set(0, 0, 0);
    this.mantleCooldown = C.mantle.cooldown;
    this.emit('mantle', ledge.top);
    return true;
  }

  _findLedge() {
    const f = this.forward;
    const feet = this.position.y;
    let best = null;
    let bestTop = -Infinity;

    for (const dist of [0.68, 1.0, 1.22]) {
      const px = this.position.x + f.x * dist;
      const pz = this.position.z + f.z * dist;
      for (const { box } of this.world.colliders) {
        const top = box.max.y;
        if (top < feet + C.mantle.minHeight || top > feet + C.mantle.maxHeight) continue;
        if (px < box.min.x - 0.08 || px > box.max.x + 0.08 || pz < box.min.z - 0.08 || pz > box.max.z + 0.08) continue;
        if (top <= bestTop) continue;
        if (!this._hasHeadroom(top, px, pz)) continue;
        bestTop = top;
        best = {
          top,
          x: this.position.x + f.x * (dist + 0.36),
          z: this.position.z + f.z * (dist + 0.36),
          dirX: f.x,
          dirZ: f.z,
        };
      }
    }
    return best;
  }

  _hasHeadroom(top, x, z) {
    const head = top + this.standingHeight - 0.05;
    for (const { box } of this.world.colliders) {
      if (box.max.y <= top + 0.05 || box.min.y >= head) continue;
      if (x > box.min.x - this.radius * 0.7 && x < box.max.x + this.radius * 0.7 &&
          z > box.min.z - this.radius * 0.7 && z < box.max.z + this.radius * 0.7) return false;
    }
    return true;
  }

  _updateMantle(dt) {
    const m = this._mantle;
    if (!m) { this.mantling = false; return; }
    m.t += dt;
    const t = clamp(m.t / m.duration, 0, 1);

    // Up first, then over the lip. Reads as a fast arcade pull-up.
    const up = easeOutCubic(Math.min(1, t / 0.68));
    const over = easeInOutCubic(clamp((t - 0.22) / 0.78, 0, 1));
    this.position.y = m.start.y + (m.end.y - m.start.y) * up;
    this.position.x = m.start.x + (m.end.x - m.start.x) * over;
    this.position.z = m.start.z + (m.end.z - m.start.z) * over;
    this.eyeTarget = C.player.eyeStanding - 0.15 + Math.sin(t * Math.PI) * 0.1;

    if (t >= 1) {
      this.position.copy(m.end);
      this.grounded = true;
      this.mantling = false;
      this._mantle = null;
      const exitSpeed = Math.max(3.2, Math.min(C.movement.sprintSpeed, m.speed * 0.94));
      this.velocity.set(m.dirX * exitSpeed, 0, m.dirZ * exitSpeed);
      this.mantleCooldown = C.mantle.cooldown;
      this.emit('mantleEnd');
    }
  }

  // ── Camera presentation ────────────────────────────────────────────────────
  _updateCamera(dt) {
    const speed = Math.hypot(this.velocity.x, this.velocity.z);
    const targetEye = this.sliding ? C.player.eyeSliding : (this.crouching ? C.player.eyeSliding + 0.12 : C.player.eyeStanding);
    this.eyeTarget = this.mantling ? this.eyeTarget : targetEye;
    this.eyeHeight = damp(this.eyeHeight, this.eyeTarget, 14, dt);

    // Bob frequency is speed-driven, amplitude is subtle so aiming stays crisp.
    if (this.grounded && speed > 0.5) {
      this.bobPhase += dt * (C.camera.bobFrequency + speed * 0.36);
    }
    const moving = this.grounded ? Math.min(1, speed / C.movement.walkSpeed) : 0;
    const bobAmp = C.camera.bobAmount * moving * (this.sliding ? 1.9 : 1);
    this.bobOffset = Math.sin(this.bobPhase * 2) * bobAmp - this.landDip;
    this.bobX = Math.cos(this.bobPhase) * bobAmp * 1.75;

    this.landDip = damp(this.landDip, 0, 8.5, dt);
    this.landSpring = damp(this.landSpring, 0, 12, dt);

    // Turn the camera into the slide direction for juice, not for control.
    const slideTurn = this.sliding ? clamp((this._slideTurn || 0) * -0.012, -0.06, 0.06) : 0;
    const lateralLean = -clamp(this.velocity.dot(new THREE.Vector3(Math.cos(this.yaw), 0, -Math.sin(this.yaw))) * 0.0022, -0.022, 0.022);
    this.slideRoll = damp(this.slideRoll, slideTurn, 8, dt);
    this.strafeRoll = damp(this.strafeRoll, lateralLean, 7, dt);

    // Dynamic FOV: speed does the talking, sprint and slide add a little drama.
    let fovTarget = C.camera.baseFov + this.speedRatio * C.camera.sprintFov;
    if (this.sprinting) fovTarget += 2.2;
    if (this.sliding) fovTarget += C.camera.slideFov;
    if (this.airborne && speed > 9) fovTarget += C.camera.airFov;
    this.fov = damp(this.fov, clamp(fovTarget, C.camera.baseFov, 104), C.camera.fovLerp, dt);

    const roll = this.slideRoll + this.strafeRoll;
    this.camera.position.set(
      this.position.x + this.bobX,
      this.position.y + this.eyeHeight + this.bobOffset,
      this.position.z
    );
    this.camera.rotation.order = 'YXZ';
    this.camera.rotation.set(this.pitch, this.yaw, roll);
    this.camera.fov = this.fov;
    this.camera.updateProjectionMatrix();
  }

  // Used by the HUD, weapon and audio layers.
  getState() {
    return {
      speed: this.horizontalSpeed,
      grounded: this.grounded,
      sliding: this.sliding,
      crouching: this.crouching,
      sprinting: this.sprinting,
      airborne: this.airborne,
      mantling: this.mantling,
      bhop: this.grounded && this.jumpBuffer > 0,
      airTime: this.airTime,
      slideTime: this.slideTime,
      yaw: this.yaw,
    };
  }
}

// Small guard keeps the mid-air ledge check from calling normalize() on zero.
function intoLedgeGuard(velocity, forward) {
  const speed = Math.hypot(velocity.x, velocity.z);
  if (speed < 1) return false;
  return (velocity.x * forward.x + velocity.z * forward.z) / speed > 0.55;
}

import * as THREE from 'three';
import { CONFIG as C } from './config.js';

// ─────────────────────────────────────────────────────────────────────────────
// The arena is assembled procedurally: no external models or textures.
// That keeps the build tiny and lets every surface share a consistent,
// sun-bleached industrial look.
// ─────────────────────────────────────────────────────────────────────────────

const rng = (seed) => () => {
  seed |= 0; seed = seed + 0x6D2B79F5 | 0;
  let t = Math.imul(seed ^ seed >>> 15, 1 | seed);
  t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
  return ((t ^ t >>> 14) >>> 0) / 4294967296;
};

function texture(size, draw, renderer, repeatX = 1, repeatY = 1) {
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = size;
  const ctx = canvas.getContext('2d');
  draw(ctx, size);
  const tex = new THREE.CanvasTexture(canvas);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(repeatX, repeatY);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = Math.min(8, renderer.capabilities.getMaxAnisotropy());
  return tex;
}

function concreteTexture(renderer, seed = 3, base = '#8f887b') {
  return texture(512, (ctx, s) => {
    const rand = rng(seed);
    ctx.fillStyle = base; ctx.fillRect(0, 0, s, s);
    // Aggregate / dust speckle.
    for (let i = 0; i < 18000; i++) {
      const v = (rand() * 42 - 21) | 0;
      ctx.fillStyle = `rgba(${v > 0 ? 255 : 0},${v > 0 ? 250 : 0},${v > 0 ? 236 : 0},${rand() * .11})`;
      const r = rand() * 2.1;
      ctx.fillRect(rand() * s, rand() * s, r, r);
    }
    // Damp patches.
    for (let i = 0; i < 8; i++) {
      const x = rand() * s, y = rand() * s, r = 25 + rand() * 90;
      const grd = ctx.createRadialGradient(x, y, 0, x, y, r);
      grd.addColorStop(0, `rgba(54,48,40,${.03 + rand() * .08})`);
      grd.addColorStop(1, 'rgba(54,48,40,0)');
      ctx.fillStyle = grd; ctx.fillRect(x - r, y - r, r * 2, r * 2);
    }
    // Hairline cracks.
    ctx.lineCap = 'round';
    for (let i = 0; i < 9; i++) {
      ctx.beginPath();
      let x = rand() * s, y = rand() * s;
      ctx.moveTo(x, y);
      for (let j = 0; j < 7; j++) {
        x += rand() * 34 - 17; y += rand() * 34 - 17;
        ctx.lineTo(x, y);
      }
      ctx.strokeStyle = `rgba(43,39,34,${.08 + rand() * .18})`;
      ctx.lineWidth = .6 + rand();
      ctx.stroke();
    }
    // Chipped paint / stains.
    for (let i = 0; i < 95; i++) {
      ctx.fillStyle = `rgba(${rand() > .55 ? '239,232,218' : '47,42,36'},${rand() * .08})`;
      ctx.beginPath(); ctx.ellipse(rand() * s, rand() * s, 1 + rand() * 9, 1 + rand() * 5, rand() * 3, 0, 6.3); ctx.fill();
    }
  }, renderer, 3, 3);
}

function asphaltTexture(renderer) {
  return texture(512, (ctx, s) => {
    const rand = rng(11);
    ctx.fillStyle = '#777065'; ctx.fillRect(0, 0, s, s);
    for (let i = 0; i < 26000; i++) {
      const light = rand() > .48;
      ctx.fillStyle = light ? `rgba(221,210,190,${rand() * .13})` : `rgba(26,23,20,${rand() * .16})`;
      ctx.fillRect(rand() * s, rand() * s, 1 + rand() * 2.4, 1 + rand() * 2.4);
    }
    // Faint tyre burn and oil.
    for (let i = 0; i < 6; i++) {
      const x = rand() * s, y = rand() * s;
      const grd = ctx.createRadialGradient(x, y, 0, x, y, 30 + rand() * 90);
      grd.addColorStop(0, 'rgba(25,22,19,.2)');
      grd.addColorStop(1, 'rgba(25,22,19,0)');
      ctx.fillStyle = grd; ctx.fillRect(0, 0, s, s);
    }
    ctx.strokeStyle = 'rgba(40,36,31,.3)'; ctx.lineWidth = 1.1;
    for (let i = 0; i < 5; i++) {
      ctx.beginPath(); let x = rand() * s, y = rand() * s; ctx.moveTo(x, y);
      for (let j = 0; j < 5; j++) { x += rand() * 40 - 20; y += rand() * 40 - 20; ctx.lineTo(x, y); }
      ctx.stroke();
    }
  }, renderer, 10, 10);
}

function containerTexture(renderer, base, seed) {
  return texture(512, (ctx, s) => {
    const rand = rng(seed);
    ctx.fillStyle = base; ctx.fillRect(0, 0, s, s);
    // Corrugation.
    for (let x = 0; x < s; x += 26) {
      const grd = ctx.createLinearGradient(x, 0, x + 26, 0);
      grd.addColorStop(0, 'rgba(255,255,255,.09)');
      grd.addColorStop(.42, 'rgba(255,255,255,.015)');
      grd.addColorStop(.58, 'rgba(0,0,0,.12)');
      grd.addColorStop(1, 'rgba(0,0,0,.03)');
      ctx.fillStyle = grd; ctx.fillRect(x, 0, 26, s);
    }
    // Rust blooms.
    for (let i = 0; i < 36; i++) {
      const x = rand() * s, y = rand() * s, r = 4 + rand() * 30;
      const grd = ctx.createRadialGradient(x, y, 0, x, y, r);
      grd.addColorStop(0, `rgba(63,39,25,${.14 + rand() * .3})`);
      grd.addColorStop(.55, `rgba(108,60,31,${.1 + rand() * .14})`);
      grd.addColorStop(1, 'rgba(108,60,31,0)');
      ctx.fillStyle = grd; ctx.fillRect(x - r, y - r, r * 2, r * 2);
    }
    // Scuffs and drips.
    for (let i = 0; i < 50; i++) {
      ctx.fillStyle = `rgba(238,231,216,${rand() * .045})`;
      ctx.fillRect(rand() * s, rand() * s, 1 + rand() * 12, .5 + rand() * 1.2);
    }
    // Horizontal rails.
    ctx.fillStyle = 'rgba(0,0,0,.17)'; ctx.fillRect(0, 4, s, 8); ctx.fillRect(0, s - 12, s, 8);
  }, renderer, 2, 1);
}

function woodTexture(renderer) {
  return texture(256, (ctx, s) => {
    const rand = rng(21);
    ctx.fillStyle = '#9b7547'; ctx.fillRect(0, 0, s, s);
    for (let i = 0; i < 80; i++) {
      ctx.strokeStyle = `rgba(${rand() > .5 ? '53,37,22' : '232,190,133'},${.03 + rand() * .11})`;
      ctx.lineWidth = .5 + rand() * 2;
      ctx.beginPath();
      const y = rand() * s;
      ctx.moveTo(0, y);
      for (let x = 0; x < s; x += 14) ctx.lineTo(x, y + Math.sin(x * .07 + i) * 2);
      ctx.stroke();
    }
    ctx.strokeStyle = 'rgba(48,35,23,.35)'; ctx.lineWidth = 5;
    for (let x = 0; x < s; x += 64) { ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, s); ctx.stroke(); }
    for (let i = 0; i < 8; i++) {
      const x = rand() * s, y = rand() * s;
      ctx.fillStyle = 'rgba(45,32,20,.5)'; ctx.beginPath(); ctx.arc(x, y, 2, 0, 6.3); ctx.fill();
    }
  }, renderer, 2, 2);
}

function hazardTexture(renderer) {
  return texture(256, (ctx, s) => {
    ctx.fillStyle = '#d6a72e'; ctx.fillRect(0, 0, s, s);
    ctx.fillStyle = '#171412';
    for (let i = -s; i < s * 2; i += 56) {
      ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i + 30, 0); ctx.lineTo(i + 30 - s, s); ctx.lineTo(i - s, s); ctx.fill();
    }
    const rand = rng(9);
    for (let i = 0; i < 2200; i++) {
      ctx.fillStyle = `rgba(240,230,210,${rand() * .09})`;
      ctx.fillRect(rand() * s, rand() * s, 1, 1);
    }
  }, renderer, 3, 1);
}

function labelTexture(renderer, title, sub, fg = '#efe7d9', bg = null, accent = '#ff5b1a') {
  return texture(1024, (ctx, s) => {
    if (bg) { ctx.fillStyle = bg; ctx.fillRect(0, 0, s, s); }
    else ctx.clearRect(0, 0, s, s);
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    if (sub) {
      ctx.font = '600 44px "IBM Plex Mono", monospace';
      ctx.fillStyle = accent; ctx.fillText(sub, s / 2, s * .29);
    }
    ctx.font = '900 176px "Barlow Condensed", sans-serif';
    ctx.fillStyle = fg; ctx.fillText(title, s / 2, s * .55);
    // Distress.
    const rand = rng(title.length * 19 + 4);
    ctx.globalCompositeOperation = 'destination-out';
    for (let i = 0; i < 160; i++) {
      ctx.fillStyle = `rgba(0,0,0,${rand() * .45})`;
      ctx.fillRect(rand() * s, rand() * s, 1 + rand() * 10, 1 + rand() * 4);
    }
  }, renderer, 1, 1);
}

function floorDecalTexture(renderer, text, color = '#d9c9b0') {
  return texture(512, (ctx, s) => {
    ctx.clearRect(0, 0, s, s);
    ctx.save();
    ctx.translate(s / 2, s / 2); ctx.rotate(-Math.PI / 2);
    ctx.font = '900 300px "Barlow Condensed", sans-serif';
    ctx.fillStyle = color; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillText(text, 0, 0); ctx.restore();
    const rand = rng(text.length + 14);
    ctx.globalCompositeOperation = 'destination-out';
    for (let i = 0; i < 600; i++) {
      ctx.fillStyle = `rgba(0,0,0,${rand() * .5})`;
      ctx.fillRect(rand() * s, rand() * s, 1 + rand() * 8, 1 + rand() * 4);
    }
  }, renderer, 1, 1);
}

// ─────────────────────────────────────────────────────────────────────────────
export function buildWorld(scene, renderer) {
  const colliders = [];
  const hitMeshes = [];
  const tickers = [];
  const bubbles = [];
  const root = new THREE.Group();
  scene.add(root);

  const rand = rng(782);
  const maxAniso = renderer.capabilities.getMaxAnisotropy();

  // ── Materials ─────────────────────────────────────────────────────────────
  const concrete = new THREE.MeshStandardMaterial({ map: concreteTexture(renderer, 3, '#8c8578'), roughness: .94, metalness: .02 });
  const concreteDark = new THREE.MeshStandardMaterial({ map: concreteTexture(renderer, 8, '#625d54'), roughness: .97, metalness: .02 });
  const floorMat = new THREE.MeshStandardMaterial({ map: asphaltTexture(renderer), roughness: .97, metalness: .02, color: 0xb5aa99 });
  const containerOrange = new THREE.MeshStandardMaterial({ map: containerTexture(renderer, '#9e4524', 2), roughness: .7, metalness: .5, color: 0xd5a17c });
  const containerBlue = new THREE.MeshStandardMaterial({ map: containerTexture(renderer, '#334d57', 9), roughness: .72, metalness: .48, color: 0xa3bcc2 });
  const containerGreen = new THREE.MeshStandardMaterial({ map: containerTexture(renderer, '#49563c', 5), roughness: .8, metalness: .35, color: 0xa7b096 });
  const wood = new THREE.MeshStandardMaterial({ map: woodTexture(renderer), roughness: .88, metalness: 0 });
  const hazard = new THREE.MeshStandardMaterial({ map: hazardTexture(renderer), roughness: .8, metalness: .1 });
  const metal = new THREE.MeshStandardMaterial({ color: 0x3e4140, roughness: .5, metalness: .8 });
  const darkMetal = new THREE.MeshStandardMaterial({ color: 0x1e201f, roughness: .58, metalness: .7 });
  const orangePaint = new THREE.MeshStandardMaterial({ color: 0xe65b1f, roughness: .65, metalness: .2 });
  const rubber = new THREE.MeshStandardMaterial({ color: 0x181a19, roughness: .84 });
  const glassMat = new THREE.MeshStandardMaterial({ color: 0x3c5960, roughness: .18, metalness: .65, emissive: 0x0b151a, emissiveIntensity: 1 });

  // ── Helpers ───────────────────────────────────────────────────────────────
  const addCollider = (x, y, z, w, h, d, type = 'hard') => {
    const box = new THREE.Box3(
      new THREE.Vector3(x - w / 2, y, z - d / 2),
      new THREE.Vector3(x + w / 2, y + h, z + d / 2)
    );
    colliders.push({ box, type });
    return box;
  };

  const box = (x, y, z, w, h, d, mat, { collide = true, rotY = 0, shadow = true, hit = true, type = 'hard' } = {}) => {
    const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
    mesh.position.set(x, y + h / 2, z);
    mesh.rotation.y = rotY;
    mesh.castShadow = shadow;
    mesh.receiveShadow = true;
    root.add(mesh);
    if (hit) hitMeshes.push(mesh);
    if (collide) {
      if (rotY) {
        const c = Math.abs(Math.cos(rotY)), s = Math.abs(Math.sin(rotY));
        addCollider(x, y, z, w * c + d * s, h, w * s + d * c, type);
      } else addCollider(x, y, z, w, h, d, type);
    }
    return mesh;
  };

  const cyl = (x, y, z, rt, rb, h, mat, segments = 12, collide = false) => {
    const mesh = new THREE.Mesh(new THREE.CylinderGeometry(rt, rb, h, segments), mat);
    mesh.position.set(x, y + h / 2, z);
    mesh.castShadow = true; mesh.receiveShadow = true;
    root.add(mesh); hitMeshes.push(mesh);
    if (collide) addCollider(x, y, z, rt * 2, h, rt * 2);
    return mesh;
  };

  const plane = (x, y, z, w, h, mat, rotX = -Math.PI / 2, rotY = 0, receive = true) => {
    const mesh = new THREE.Mesh(new THREE.PlaneGeometry(w, h), mat);
    mesh.position.set(x, y, z);
    mesh.rotation.set(rotX, rotY, 0);
    mesh.receiveShadow = receive;
    root.add(mesh);
    return mesh;
  };

  const label = (text, sub, x, y, z, w, h, rotY = 0, bg = null) => {
    const tex = labelTexture(renderer, text, sub, '#efe7d9', bg, '#ff5b1a');
    const mat = new THREE.MeshStandardMaterial({
      map: tex, transparent: true, roughness: .8, metalness: .05,
      polygonOffset: true, polygonOffsetFactor: -2, side: THREE.DoubleSide,
    });
    const mesh = plane(x, y, z, w, h, mat, 0, rotY, false);
    mesh.castShadow = false;
    return mesh;
  };

  // ── Sky ───────────────────────────────────────────────────────────────────
  const sunDir = new THREE.Vector3(-0.54, 0.26, -0.80).normalize();
  const sky = new THREE.Mesh(
    new THREE.SphereGeometry(210, 40, 20),
    new THREE.ShaderMaterial({
      side: THREE.BackSide, depthWrite: false, fog: false,
      uniforms: {
        top: { value: new THREE.Color('#3b5367') },
        mid: { value: new THREE.Color('#b7b5a8') },
        horizon: { value: new THREE.Color('#efc28d') },
        ground: { value: new THREE.Color('#a57850') },
        sunDir: { value: sunDir },
      },
      vertexShader: `
        varying vec3 vDir;
        void main() {
          vDir = normalize(position);
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
      `,
      fragmentShader: `
        varying vec3 vDir;
        uniform vec3 top, mid, horizon, ground, sunDir;
        float hash(vec2 p){ return fract(sin(dot(p, vec2(127.1,311.7))) * 43758.5453); }
        float noise(vec2 p){ vec2 i=floor(p), f=fract(p); f=f*f*(3.0-2.0*f);
          return mix(mix(hash(i),hash(i+vec2(1,0)),f.x),mix(hash(i+vec2(0,1)),hash(i+vec2(1,1)),f.x),f.y); }
        void main() {
          vec3 d = normalize(vDir);
          float h = max(d.y, 0.0);
          vec3 col = mix(horizon, mid, smoothstep(0.0, 0.22, h));
          col = mix(col, top, smoothstep(0.16, 0.72, h));
          col = mix(col, ground, smoothstep(0.0, -0.2, d.y));
          float sun = max(dot(d, sunDir), 0.0);
          col += vec3(1.0, .68, .35) * pow(sun, 42.0) * .35;
          col += vec3(1.0, .78, .50) * pow(sun, 500.0) * 1.9;
          col += vec3(1.0, .55, .22) * pow(max(0.0, 1.0 - abs(d.y)), 8.0) * .05;
          // Thin drifting cloud bands.
          vec2 p = d.xz / max(d.y + 0.18, 0.08) * 1.4;
          float n = noise(p * 1.5 + 3.2) * .56 + noise(p * 3.7) * .28 + noise(p * 7.9) * .16;
          float cloud = smoothstep(.52, .82, n) * smoothstep(-.01, .1, d.y) * .38;
          col = mix(col, vec3(.88,.80,.72), cloud);
          gl_FragColor = vec4(col, 1.0);
        }
      `,
    })
  );
  sky.renderOrder = -10;
  scene.add(sky);

  // Sun light + warm bounce.
  const sun = new THREE.DirectionalLight(0xffd5a4, 3.0);
  sun.position.copy(sunDir).multiplyScalar(55);
  sun.castShadow = true;
  sun.shadow.mapSize.set(2048, 2048);
  sun.shadow.camera.left = -40; sun.shadow.camera.right = 40;
  sun.shadow.camera.top = 40; sun.shadow.camera.bottom = -40;
  sun.shadow.camera.near = 1; sun.shadow.camera.far = 120;
  sun.shadow.bias = -0.00045;
  sun.shadow.normalBias = 0.038;
  scene.add(sun); scene.add(sun.target);

  const hemi = new THREE.HemisphereLight(0xb9d2df, 0x5a4631, 1.5);
  scene.add(hemi);
  const fill = new THREE.DirectionalLight(0x6d8baa, .5);
