  label('SLIDE', 'CLEARANCE 1.4M', cX - cW / 2 - .08, cBottom + 1.1, cZ, 2.6, 1.6, -Math.PI / 2, '#1b1612');
  // Climb crates next to the container.
  box(cX + cW / 2 + .85, 0, cZ + .7, 1.5, .8, 1.5, wood);
  box(cX + cW / 2 + .85, .8, cZ + .7, 1.5, .8, 1.5, wood);
  box(cX + cW / 2 + .85, 1.6, cZ + .7, 1.5, .8, 1.5, wood);

  // ── Left-side industrial block ─────────────────────────────────────────────
  const bx = -16.3, bz = 1.5;
  box(bx, 0, bz, 9.8, 4.2, 7.8, concreteDark);
  // Roof lip.
  box(bx, 4.2, bz, 10.2, .32, 8.2, concrete);
  // Windows.
  for (let i = 0; i < 3; i++) {
    box(bx - 2.7 + i * 2.7, 2.45, bz + 3.96, 1.3, .95, .05, glassMat, { hit: false, collide: false, shadow: false });
    box(bx - 2.7 + i * 2.7, 2.41, bz + 4.01, 1.36, .07, .08, darkMetal, { hit: false, collide: false, shadow: false });
  }
  // Door and canopy.
  box(bx + 1.0, 0, bz + 4.01, 1.35, 2.3, .08, darkMetal, { hit: false, collide: false });
  box(bx + 1.0, 2.55, bz + 4.2, 2.0, .14, .7, orangePaint, { hit: false, collide: false });
  label('BAY 04', 'MANUTENÇÃO', bx - 2.9, 3.45, bz + 3.99, 2.3, 1.0, 0);
  // Rooftop AC + antenna.
  box(bx - 2.8, 4.52, bz - 1.0, 1.4, .75, 1.1, metal);
  box(bx - 2.8, 5.27, bz - 1.0, 1.7, .1, 1.35, darkMetal, { hit: false });
  cyl(bx + 2.7, 4.52, bz - 1.2, .04, .06, 3.5, darkMetal, 6);
  box(bx + 2.7, 7.9, bz - 1.2, .55, .05, .18, orangePaint, { hit: false, collide: false });

  // ── Far-left training platform + steps ────────────────────────────────────
  const plX = -16.5, plZ = -10.5;
  box(plX, 0, plZ, 8.2, 1.9, 6.2, concrete);
  box(plX, 1.9, plZ, 8.5, .18, 6.5, concreteDark);
  // Steps (0.38 rise is within stepHeight).
  for (let i = 0; i < 5; i++) {
    box(plX, 0, plZ + 3.6 + i * .55, 3.8, .38 * (5 - i), .6, concreteDark);
  }
  // Railings.
  for (const xo of [-3.8, 3.8]) {
    for (let i = 0; i < 4; i++) {
      box(plX + xo, 2.08, plZ - 2.8 + i * 1.8, .07, 1.1, .07, metal, { hit: false, collide: false });
    }
    box(plX + xo, 3.08, plZ - .2, .08, .08, 5.6, metal, { hit: false, collide: false });
  }
  // Crates on the platform: mantle chain.
  box(plX + 2.3, 2.08, plZ - 1.9, 1.4, .9, 1.4, wood);
  box(plX + 2.3, 2.98, plZ - 1.9, 1.2, .75, 1.2, wood);
  label('TRAINING', 'PLATAFORMA 02', plX - 2.3, 2.95, plZ + 3.12, 3.0, 1.1, Math.PI);

  // ── Central cover / mantle playground ─────────────────────────────────────
  // Low concrete walls, deliberately 1.0–1.4m for instant mantles.
  box(-6.8, 0, 12.2, 6.2, 1.05, .58, concrete);
  box(-6.8, 1.05, 12.5, 1.1, .35, 1.0, concrete, { hit: false });
  box(1.2, 0, 7.1, 5.2, 1.28, .52, concreteDark);
  box(1.2, 1.28, 7.1, 5.25, .1, .6, hazard, { hit: false });

  // Jersey barriers, arranged like a slalom.
  const barrier = (x, z, rot) => {
    const g = new THREE.Group();
    const base = new THREE.Mesh(new THREE.BoxGeometry(2.3, .42, .68), concrete);
    base.position.y = .21;
    const top = new THREE.Mesh(new THREE.BoxGeometry(2.3, .68, .3), concrete);
    top.position.y = .76;
    const stripes = new THREE.Mesh(new THREE.PlaneGeometry(2.1, .13), hazard);
    stripes.position.set(0, .88, .155);
    stripes.rotation.x = 0;
    g.add(base, top, stripes);
    g.position.set(x, 0, z); g.rotation.y = rot;
    g.traverse(o => { if (o.isMesh) { o.castShadow = true; o.receiveShadow = true; hitMeshes.push(o); } });
    root.add(g);
    // Conservative AABB for the rotated barrier.
    const s = Math.abs(Math.sin(rot)), c = Math.abs(Math.cos(rot));
    addCollider(x, 0, z, 2.3 * c + .68 * s, 1.1, 2.3 * s + .68 * c);
  };
  barrier(3.9, 13.0, .18);
  barrier(-3.2, 1.0, -.32);
  barrier(7.6, -6.0, .7);
  barrier(-9.6, -2.1, .12);

  // Central crate stack / route to the catwalk.
  const crate = (x, y, z, s = 1.55, rot = 0) => box(x, y, z, s, s, s, wood, { rotY: rot });
  crate(4.9, 0, 17.2, 1.7, .08);
  crate(5.2, 1.7, 17.2, 1.35, -.12);
  crate(6.7, 0, 18.0, 1.25, .03);
  crate(-3.6, 0, 16.5, 1.3, .22);
  crate(-5.0, 0, 5.1, 1.6, -.07);
  crate(-5.0, 1.6, 5.1, 1.25, .17);
  crate(12.8, 0, 10.5, 1.4, -.14);
  crate(13.7, 0, 9.4, 1.1, .31);

  // ── Slide gate / low wall across a side lane ──────────────────────────────
  box(-14.6, 0, 15.1, .45, 2.0, 3.1, concrete); // jamb
  box(-9.2, 0, 15.1, .45, 2.0, 3.1, concrete);
  box(-11.9, 1.42, 15.1, 5.9, .48, .38, concreteDark); // lintel: 1.42 clearance
  box(-11.9, 1.9, 15.1, 5.9, .1, .42, hazard, { hit: false });
  label('DUCK', '1.3M', -11.9, 1.7, 14.9, 1.8, .55, Math.PI);

  // ── Back lane containers ──────────────────────────────────────────────────
  box(17.4, 0, -15.2, 8.6, 2.6, 3.0, containerBlue, { rotY: Math.PI / 2 });
  box(-2.2, 0, -17.8, 9.4, 2.6, 3.0, containerGreen);
  box(-2.2, 2.6, -17.8, 9.4, 2.6, 3.0, containerOrange);
  // Small climb stack beside container.
  crate(-8.2, 0, -15.2, 1.2);
  crate(-8.2, 1.2, -15.2, 1.1);
  crate(-8.2, 2.3, -15.2, 1.0);
  // Loading dock.
  box(12, 0, -22.2, 17, 1.15, 3.4, concreteDark);
  box(12, 1.15, -22.2, 17.2, .12, 3.6, concrete);
  for (let i = 0; i < 3; i++) {
    box(5.2 + i * 7.2, 1.27, -22.2, 2.8, .05, 2.7, darkMetal, { hit: false, collide: false });
  }
  label('LOADING', 'DOCA 02', 12, 2.65, -24.0, 6.2, 1.7, 0);

  // ── Scaffold / catwalk around the central lane ────────────────────────────
  const scafMat = metal;
  for (const x of [-10.8, -4.4]) {
    for (const z of [-5.9, -1.8, 2.3]) {
      box(x, 0, z, .13, 3.35, .13, scafMat, { hit: false, collide: false });
    }
    box(x, 3.25, -1.8, .16, .16, 8.1, scafMat, { hit: false, collide: false });
  }
  // Catwalk deck at 3.3, reachable from the rooftop of the central block? Decor.
  box(-7.6, 3.18, -1.8, 6.5, .23, 1.1, darkMetal, { collide: false, hit: false });
  for (let i = 0; i < 9; i++) {
    box(-10.4 + i * .7, 3.43, -1.8, .05, .1, 1.2, metal, { hit: false, collide: false, shadow: false });
  }
  // Wooden pallet + tarp lean-to at the side.
  box(18.9, 0, 15.8, 2.6, .2, 2.6, wood, { rotY: .1 });
  box(18.9, .2, 15.8, 2.4, 1.5, 1.8, wood, { rotY: -.1 });

  // ── Barrels, lamps, cables ────────────────────────────────────────────────
  const barrelMat = new THREE.MeshStandardMaterial({ color: 0x7f3d1d, roughness: .74, metalness: .4 });
  const barrelBlue = new THREE.MeshStandardMaterial({ color: 0x324a51, roughness: .7, metalness: .45 });
  for (const [x, z, m] of [[-12.9, 7.2, barrelMat], [-13.7, 7.5, barrelBlue], [8.8, 12.2, barrelBlue], [20.8, 5.2, barrelMat], [-4.9, -12.9, barrelMat]]) {
    const b = cyl(x, 0, z, .36, .36, .9, m, 14, true);
    b.castShadow = true;
    for (const ry of [.2, .68]) {
      const ring = new THREE.Mesh(new THREE.TorusGeometry(.365, .025, 5, 16), darkMetal);
      ring.position.set(x, ry, z); ring.rotation.x = Math.PI / 2; root.add(ring);
    }
  }

  // Bollards and lamp posts.
  const lampLights = [];
  for (const [x, z, ry] of [[-21, 20, .4], [20.8, 18.5, -.8], [22.5, -7.5, 2.1]]) {
    cyl(x, 0, z, .09, .13, 4.8, metal, 8, true);
    const head = box(x + Math.sin(ry) * .55, 4.65, z + Math.cos(ry) * .55, .62, .2, .34, darkMetal, { hit: false, collide: false });
    const bulb = new THREE.Mesh(new THREE.BoxGeometry(.48, .035, .25), new THREE.MeshBasicMaterial({ color: 0xffd9a0 }));
    bulb.position.copy(head.position).add(new THREE.Vector3(0, -.11, 0)); root.add(bulb);
    const light = new THREE.PointLight(0xffc883, 7, 11, 2);
    light.position.copy(head.position).add(new THREE.Vector3(0, -.45, 0));
    scene.add(light); lampLights.push(light);
  }

  // Cables overhead.
  const cableMat = new THREE.MeshBasicMaterial({ color: 0x171513 });
  for (let i = 0; i < 4; i++) {
    const y = 4.1 + i * .22;
    const curve = new THREE.CatmullRomCurve3([
      new THREE.Vector3(-per + 1, y, 18 - i * 7),
      new THREE.Vector3(-8, y - .7 - rand() * .5, 17 - i * 7),
      new THREE.Vector3(4, y - .25, 16 - i * 7),
      new THREE.Vector3(per - 1, y - .8, 15 - i * 7),
    ]);
    const tube = new THREE.Mesh(new THREE.TubeGeometry(curve, 18, .018, 4, false), cableMat);
    tube.castShadow = false; root.add(tube);
  }

  // Hanging banners.
  const bannerMat = new THREE.MeshStandardMaterial({ color: 0xd84f19, roughness: .9, side: THREE.DoubleSide });
  for (const [x, z, w] of [[-10.6, 8.2, 1.35], [-7.0, 8.2, 1.35], [16.4, -7.5, 1.4]]) {
    const banner = new THREE.Mesh(new THREE.PlaneGeometry(w, 2.2, 4, 8), bannerMat);
    banner.position.set(x, 3.25, z);
    banner.rotation.y = Math.PI / 2;
    banner.castShadow = true;
    // A little cloth ripple.
    const pos = banner.geometry.attributes.position;
    for (let i = 0; i < pos.count; i++) {
      const px = pos.getX(i), py = pos.getY(i);
      pos.setZ(i, Math.sin(px * 2.4 + py * 1.8) * .07);
    }
    pos.needsUpdate = true;
    root.add(banner);
    label('07', 'COMBAT', x + .015, 3.25, z, 1.15, .8, Math.PI / 2).rotation.z = Math.PI;
  }

  // A small fire barrel for a warm pool of light.
  const fireX = 19.2, fireZ = -2.2;
  cyl(fireX, 0, fireZ, .43, .4, .95, barrelMat, 14, true);
  const ember = new THREE.Mesh(new THREE.CircleGeometry(.34, 12), new THREE.MeshBasicMaterial({ color: 0xff7b24 }));
  ember.rotation.x = -Math.PI / 2; ember.position.set(fireX, .96, fireZ); root.add(ember);
  const fireLight = new THREE.PointLight(0xff6f29, 13, 10, 2);
  fireLight.position.set(fireX, 1.45, fireZ);
  scene.add(fireLight);
  fireLight.userData.base = 13;

  // ── Distant skyline ───────────────────────────────────────────────────────
  const skylineMat = new THREE.MeshBasicMaterial({ color: 0x6a5949, fog: true });
  const skylineMat2 = new THREE.MeshBasicMaterial({ color: 0x4b4238, fog: true });
  for (let i = 0; i < 34; i++) {
    const angle = (i / 34) * Math.PI * 2 + rand() * .08;
    const radius = 75 + rand() * 35;
    const w = 5 + rand() * 12, h = 3 + rand() * 20;
    const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, w * .7), rand() > .5 ? skylineMat : skylineMat2);
    m.position.set(Math.cos(angle) * radius, h / 2 + rand() * 2, Math.sin(angle) * radius);
    root.add(m);
  }
  // Distant crane silhouette.
  const crane = new THREE.Group();
  const craneMat = new THREE.MeshBasicMaterial({ color: 0x403830, fog: true });
  const craneParts = [[0, 10, 0, .5, 20, .5], [5, 19.5, 0, 11, .35, .35], [-6, 16.8, 0, .35, 5.5, .35]];
  for (const [x, y, z, w, h, d] of craneParts) {
    const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), craneMat);
    m.position.set(x, y, z); crane.add(m);
  }
  crane.position.set(-54, 0, -58); root.add(crane);

  // ── Dust motes ────────────────────────────────────────────────────────────
  const dustCount = 520;
  const dustGeo = new THREE.BufferGeometry();
  const dustPos = new Float32Array(dustCount * 3);
  const dustSeed = new Float32Array(dustCount);
  for (let i = 0; i < dustCount; i++) {
    dustPos[i * 3] = (rand() - .5) * 54;
    dustPos[i * 3 + 1] = .3 + rand() * 8;
    dustPos[i * 3 + 2] = (rand() - .5) * 54;
    dustSeed[i] = rand() * 6.28;
  }
  dustGeo.setAttribute('position', new THREE.BufferAttribute(dustPos, 3));
  const dustMat = new THREE.PointsMaterial({
    color: 0xffd8a5, size: .035, transparent: true, opacity: .42,
    depthWrite: false, blending: THREE.AdditiveBlending, sizeAttenuation: true,
  });
  const dust = new THREE.Points(dustGeo, dustMat);
  scene.add(dust);

  // Slow, cheap drift. No per-particle objects.
  tickers.push((t) => {
    const arr = dustGeo.attributes.position.array;
    for (let i = 0; i < dustCount; i++) {
      arr[i * 3 + 1] += Math.sin(t * .18 + dustSeed[i]) * .0006;
      arr[i * 3] += .0012;
      if (arr[i * 3] > 27) arr[i * 3] = -27;
    }
    dustGeo.attributes.position.needsUpdate = true;
    fireLight.intensity = fireLight.userData.base + Math.sin(t * 17) * 2 + Math.sin(t * 31) * 1.2;
  });

  // ── Environment hit mesh list ─────────────────────────────────────────────
  // Some decorative meshes use transparent labels and shouldn't stop bullets.
  const shootable = hitMeshes.filter(m => m && m.isMesh && !m.material?.transparent);

  function update(dt, elapsed) {
    for (const fn of tickers) fn(elapsed, dt);
  }

  return {
    root, colliders, hitMeshes: shootable, spawn: C.arena.spawn,
    update, sunDir, lamps: lampLights,
    materials: { concrete, concreteDark, metal, darkMetal, wood, orangePaint, hazard },
    addCollider, box, hitMeshesAll: hitMeshes,
    fogColor: new THREE.Color(0xc8a47c),
  };
}

import * as THREE from 'three';
import { CONFIG as C } from './config.js';

// ─────────────────────────────────────────────────────────────────────────────
// First-person view model. Everything is built from primitives so it shares the
// same material/lighting language as the arena, while the animation layer runs
// independently from the physics for a 1-frame response.
// ─────────────────────────────────────────────────────────────────────────────
export class Weapon {
  constructor(camera, renderer) {
    this.camera = camera;
    this.renderer = renderer;
    this.root = new THREE.Group();
    this.rig = new THREE.Group();
    this.recoilGroup = new THREE.Group();
    this.root.add(this.rig);
    this.rig.add(this.recoilGroup);
    camera.add(this.root);

    this.recoil = 0;
    this.recoilYaw = 0;
    this.flashTime = 0;
    this.reloadTime = 0;
    this.reloading = false;
    this.base = new THREE.Vector3(0.315, -0.285, -0.52);
    this.root.position.copy(this.base);
    this.root.rotation.set(0.015, -0.025, 0.008);
    this.root.scale.setScalar(1.0);

    this._build();

    // A soft camera-side kicker keeps the gun legible against the bright arena.
    const kicker = new THREE.PointLight(0xffdfbf, 1.5, 2.2, 2);
    kicker.position.set(0.3, 0.25, 0.1);
    camera.add(kicker);
  }

  _build() {
    const body = new THREE.MeshStandardMaterial({ color: 0x242927, roughness: .48, metalness: .7 });
    const bodyDark = new THREE.MeshStandardMaterial({ color: 0x111514, roughness: .56, metalness: .62 });
    const tan = new THREE.MeshStandardMaterial({ color: 0x9b8d72, roughness: .7, metalness: .15 });
    const rubber = new THREE.MeshStandardMaterial({ color: 0x131514, roughness: .93, metalness: .02 });
    const glow = new THREE.MeshBasicMaterial({ color: 0xff3b1d });
    const metal = new THREE.MeshStandardMaterial({ color: 0x707975, roughness: .3, metalness: .95 });
    const glove = new THREE.MeshStandardMaterial({ color: 0x2e302b, roughness: .92, metalness: .02 });
    const sleeve = new THREE.MeshStandardMaterial({ color: 0x5b5c4c, roughness: .98 });
    const add = (geo, mat, x, y, z, rx = 0, ry = 0, rz = 0) => {
      const m = new THREE.Mesh(geo, mat);
      m.position.set(x, y, z); m.rotation.set(rx, ry, rz);
      this.recoilGroup.add(m);
      return m;
    };

    // Receiver + handguard.
    add(new THREE.BoxGeometry(.18, .19, .55), body, 0, 0, -.12);
    add(new THREE.BoxGeometry(.155, .16, .56), tan, 0, -.01, -.62);
    add(new THREE.BoxGeometry(.16, .035, .52), bodyDark, 0, .093, -.48);
    // Rail teeth.
    for (let i = 0; i < 9; i++) add(new THREE.BoxGeometry(.135, .022, .035), bodyDark, 0, .12, -.25 - i * .055);

    // Barrel + muzzle brake.
    const barrel = add(new THREE.CylinderGeometry(.025, .028, .55, 10), metal, 0, .02, -.98, Math.PI / 2, 0, 0);
    add(new THREE.CylinderGeometry(.045, .045, .14, 10), bodyDark, 0, .02, -1.25, Math.PI / 2, 0, 0);
    for (let i = 0; i < 3; i++) add(new THREE.BoxGeometry(.095, .015, .018), bodyDark, 0, .02, -1.19 - i * .036);
    // Gas block / front sight.
    add(new THREE.BoxGeometry(.06, .1, .06), bodyDark, 0, .105, -.94);
    add(new THREE.BoxGeometry(.04, .065, .032), bodyDark, 0, .15, -.94);
    add(new THREE.BoxGeometry(.013, .045, .013), metal, 0, .158, -.935);

    // Stock.
    add(new THREE.BoxGeometry(.09, .12, .28), body, 0, -.01, .26);
    add(new THREE.BoxGeometry(.15, .19, .12), rubber, 0, -.02, .43);
    add(new THREE.BoxGeometry(.11, .045, .17), tan, 0, .075, .27);

    // Pistol grip + magazine.
    add(new THREE.BoxGeometry(.105, .25, .13), rubber, 0, -.21, .06, .23, 0, 0);
    add(new THREE.BoxGeometry(.11, .26, .19), bodyDark, 0, -.2, -.21, -.12, 0, 0);
    add(new THREE.BoxGeometry(.12, .025, .2), tan, 0, -.07, -.21, -.12, 0, 0);
    // Trigger guard.
    add(new THREE.TorusGeometry(.062, .01, 4, 10, Math.PI * 1.4), body, 0, -.12, -.03, 0, 0, Math.PI);

    // Holo sight.
    const sightY = .17;
    add(new THREE.BoxGeometry(.13, .045, .16), bodyDark, 0, sightY, -.2);
    add(new THREE.BoxGeometry(.085, .105, .02), bodyDark, 0, sightY + .075, -.26);
    add(new THREE.BoxGeometry(.085, .105, .02), bodyDark, 0, sightY + .075, -.14);
    add(new THREE.BoxGeometry(.085, .022, .14), bodyDark, 0, sightY + .126, -.2);
    const lens = add(new THREE.BoxGeometry(.067, .082, .006), new THREE.MeshBasicMaterial({ color: 0x18352f, transparent: true, opacity: .55 }), 0, sightY + .073, -.249);
    lens.material.depthWrite = false;
    const dot = add(new THREE.CircleGeometry(.007, 10), glow, 0, sightY + .073, -.243);
    dot.material.depthTest = false;
    dot.renderOrder = 12;
    // Laser unit.
    add(new THREE.BoxGeometry(.055, .06, .11), bodyDark, -.075, .03, -.88);
    add(new THREE.CircleGeometry(.013, 10), glow, -.106, .03, -.86, 0, -Math.PI / 2, 0);

    // Gloved support hand on the handguard.
    const hand = add(new THREE.BoxGeometry(.13, .115, .19), glove, -.02, -.12, -.57, 0, 0, -.12);
    hand.geometry.translate(0, 0, 0);
    add(new THREE.BoxGeometry(.1, .065, .12), glove, .035, -.16, -.49, .1, 0, 0);
    add(new THREE.BoxGeometry(.09, .09, .22), glove, .012, -.14, -.72, -.08, 0, 0);
    add(new THREE.BoxGeometry(.11, .105, .24), sleeve, -.07, -.23, -.3, .18, 0, .05);
    // Firing hand.
    add(new THREE.BoxGeometry(.115, .13, .17), glove, .005, -.235, .045, .2, 0, -.03);
    add(new THREE.BoxGeometry(.095, .09, .22), glove, .04, -.31, .10, .35, 0, 0);
    add(new THREE.BoxGeometry(.115, .12, .27), sleeve, .07, -.39, .19, .33, 0, -.02);

    // Muzzle anchor + flash.
    this.muzzle = new THREE.Object3D();
    this.muzzle.position.set(0, .02, -1.33);
    this.recoilGroup.add(this.muzzle);

    const flashCanvas = document.createElement('canvas');
    flashCanvas.width = flashCanvas.height = 128;
    const ctx = flashCanvas.getContext('2d');
    const grd = ctx.createRadialGradient(64, 64, 0, 64, 64, 64);
    grd.addColorStop(0, 'rgba(255,255,235,1)');
    grd.addColorStop(.15, 'rgba(255,226,148,1)');
    grd.addColorStop(.38, 'rgba(255,125,34,.9)');
    grd.addColorStop(1, 'rgba(255,80,20,0)');
    ctx.fillStyle = grd; ctx.fillRect(0, 0, 128, 128);
    ctx.strokeStyle = 'rgba(255,205,120,.85)'; ctx.lineWidth = 2;
    for (let i = 0; i < 8; i++) {
      ctx.beginPath(); ctx.moveTo(64, 64);
      const a = i / 8 * Math.PI * 2 + .2;
      const len = 22 + (i % 3) * 10;
      ctx.lineTo(64 + Math.cos(a) * len, 64 + Math.sin(a) * len); ctx.stroke();
    }
    const flashTex = new THREE.CanvasTexture(flashCanvas);
    flashTex.colorSpace = THREE.SRGBColorSpace;
    const flashMat = new THREE.MeshBasicMaterial({ map: flashTex, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, depthTest: false });
    this.flash = new THREE.Group();
    for (let i = 0; i < 2; i++) {
      const p = new THREE.Mesh(new THREE.PlaneGeometry(.34, .34), flashMat);
      p.rotation.z = i * Math.PI / 2;
      p.rotation.y = Math.PI / 2;
      this.flash.add(p);
    }
    this.flash.position.copy(this.muzzle.position);
    this.flash.visible = false;
    this.recoilGroup.add(this.flash);

    // Keep a reference so the reload animation can dip the magazine.
    this.magazine = this.recoilGroup.children.find((m, i) => i === 19);
    this.lens = lens;
  }

  show() { this.root.visible = true; }
  hide() { this.root.visible = false; }

  fire() {
    this.recoil = Math.min(1, this.recoil + .55);
    this.recoilYaw = (Math.random() - .5) * .35;
    this.flashTime = .045;
    this.flash.rotation.z = Math.random() * Math.PI;
    this.flash.visible = true;
  }

  startReload() {
    this.reloading = true;
    this.reloadTime = 0;
  }

  finishReload() {
    this.reloading = false;
    this.reloadTime = 0;
  }

  getMuzzleWorld(target = new THREE.Vector3()) {
    this.muzzle.getWorldPosition(target);
    return target;
  }

  update(dt, player, firing = false) {
    const speed = player.horizontalSpeed;
    const moving = player.grounded ? Math.min(1, speed / 8.2) : .1;
    const slide = player.sliding ? 1 : 0;

    // Spring recoil.
    this.recoil = Math.max(0, this.recoil - dt * 9.5);
    this.recoilYaw *= Math.exp(-dt * 12);
    const kick = this.recoil * this.recoil * .065;

    // Sprint pose drops the gun; slide cants it. Both are fast, readable.
    const sprint = player.sprinting ? 1 : 0;
    const sprintDrop = sprint * (0.055 + Math.sin(player.bobPhase * 2) * .008);
    const slideDrop = slide * .07;

    const bobX = Math.cos(player.bobPhase) * .012 * moving;
    const bobY = Math.sin(player.bobPhase * 2) * .008 * moving;
    const air = player.airborne ? 1 : 0;
    const airLift = Math.sin(player.airTime * 5.5) * .008 * air;

    const reloadEase = this.reloading ? this.reloadTime / C.weapon.reloadTime : 0;
    const reloadArc = this.reloading ? Math.sin(Math.min(1, reloadEase) * Math.PI) : 0;

    this.root.position.set(
      this.base.x + bobX + slide * .04,
      this.base.y + bobY - sprintDrop - slideDrop + airLift - reloadArc * .12,
      this.base.z + this.recoil * .06 + reloadArc * .03
    );
    this.root.rotation.set(
      .015 + this.recoil * .07 + reloadArc * .2 - sprint * .11,
      -.025 + this.recoilYaw * .13 + sprint * .1,
      .008 + slide * .11 + Math.sin(player.bobPhase) * .005 * moving - sprint * .13
    );

    this.recoilGroup.position.z = kick * 1.75;
    this.recoilGroup.rotation.x = this.recoil * .075;

    if (this.reloading) {
      this.reloadTime += dt;
      if (this.reloadTime >= C.weapon.reloadTime) this.finishReload();
    }

    if (this.flashTime > 0) {
      this.flashTime -= dt;
      this.flash.visible = true;
      this.flash.scale.setScalar(.8 + Math.random() * .55);
      if (this.flashTime <= 0) this.flash.visible = false;
    }

    // Holo dot pulses very slightly while firing.
    if (firing) this.lens.material.opacity = .72;
    else this.lens.material.opacity = .55;
  }
}

import * as THREE from 'three';
import { CONFIG as C } from './config.js';

const _v = new THREE.Vector3();
const _v2 = new THREE.Vector3();
const _q = new THREE.Quaternion();
const _m3 = new THREE.Matrix3();
const rand = (a = 0, b = 1) => a + Math.random() * (b - a);
const damp = (a, b, rate, dt) => a + (b - a) * (1 - Math.exp(-rate * dt));

// ─────────────────────────────────────────────────────────────────────────────
// Combat layer: target dummies, hitscan, tracers, impacts and ammo.
// Kept separate from movement so the movement tuning can be tested in isolation.
// ─────────────────────────────────────────────────────────────────────────────
export class Combat {
  constructor({ scene, camera, world, player, weapon, audio, hud, onEvent }) {
    this.scene = scene;
    this.camera = camera;
    this.world = world;
    this.player = player;
    this.weapon = weapon;
    this.audio = audio;
    this.hud = hud;
    this.onEvent = onEvent || (() => {});

    this.ammo = C.weapon.magazine;
    this.cooldown = 0;
    this.reloading = false;
    this.reloadTimer = 0;
    this.score = 0;
    this.kills = 0;
    this.shots = 0;
    this.hits = 0;
    this.recoilRecover = 0;
    this.enabled = false;
    this.time = 0;

    this.effects = new THREE.Group();
    scene.add(this.effects);
    this.tracers = [];
    this.sparks = [];
    this.decalPool = [];
    this.decalIndex = 0;

    this.raycaster = new THREE.Raycaster();
    this.raycaster.far = 110;

    this.targets = [];
    this.hitboxes = [];
    this._createTargets();
    this._createDecalPool();
    this._createSparkTexture();
  }

  reset() {
    this.ammo = C.weapon.magazine;
    this.cooldown = 0;
    this.reloading = false;
    this.reloadTimer = 0;
    this.score = 0;
    this.kills = 0;
    this.shots = 0;
    this.hits = 0;
    this.time = 0;
  }

  // ── Target dummies ─────────────────────────────────────────────────────────
  _createTargets() {
    const anchors = [
      { x: -1.6, y: 0, z: -14.2, range: 1.9, phase: 0.2 },
      { x: -10.8, y: 0, z: -14.6, range: 2.2, phase: 2.1 },
      { x: 6.0, y: 0, z: -12.9, range: 1.5, phase: 4.4 },
      { x: 12.7, y: 0, z: -10.6, range: 1.2, phase: 1.1 },
      { x: -20.8, y: 0, z: 8.0, range: 1.0, phase: 3.2 },
      { x: 18.2, y: 0, z: 7.8, range: 1.4, phase: 5.0 },
      { x: 12.4, y: 1.27, z: -20.9, range: 0.8, phase: 2.8 },
      { x: -16.5, y: 2.08, z: -10.5, range: 1.3, phase: 0.8 },
    ];
    anchors.forEach((a, i) => this.targets.push(new TargetDummy(this.scene, a, i, this.audio)));
  }

  _createDecalPool() {
    const c = document.createElement('canvas');
    c.width = c.height = 64;
    const ctx = c.getContext('2d');
    const grd = ctx.createRadialGradient(32, 32, 2, 32, 32, 30);
    grd.addColorStop(0, 'rgba(8,7,6,.92)');
    grd.addColorStop(.25, 'rgba(16,14,12,.85)');
    grd.addColorStop(.55, 'rgba(42,38,33,.45)');
    grd.addColorStop(1, 'rgba(30,27,23,0)');
    ctx.fillStyle = grd; ctx.fillRect(0, 0, 64, 64);
    // Cracks.
    ctx.strokeStyle = 'rgba(20,18,15,.6)'; ctx.lineWidth = 1;
    for (let i = 0; i < 5; i++) {
      ctx.beginPath(); ctx.moveTo(32, 32);
      const a = Math.random() * Math.PI * 2;
      ctx.lineTo(32 + Math.cos(a) * rand(10, 28), 32 + Math.sin(a) * rand(10, 28)); ctx.stroke();
    }
    const tex = new THREE.CanvasTexture(c);
    tex.colorSpace = THREE.SRGBColorSpace;
    const mat = new THREE.MeshBasicMaterial({
      map: tex, transparent: true, depthWrite: false, opacity: .95,
      polygonOffset: true, polygonOffsetFactor: -4, polygonOffsetUnits: -4, side: THREE.DoubleSide,
    });
    for (let i = 0; i < 36; i++) {
      const m = new THREE.Mesh(new THREE.PlaneGeometry(.16, .16), mat);
      m.visible = false; m.renderOrder = 4;
      this.effects.add(m); this.decalPool.push(m);
    }
  }

  _createSparkTexture() {
    const c = document.createElement('canvas');
    c.width = c.height = 32;
    const ctx = c.getContext('2d');
    const grd = ctx.createRadialGradient(16, 16, 0, 16, 16, 15);
    grd.addColorStop(0, 'rgba(255,248,210,1)');
    grd.addColorStop(.3, 'rgba(255,186,82,.95)');
    grd.addColorStop(1, 'rgba(255,95,25,0)');
    ctx.fillStyle = grd; ctx.fillRect(0, 0, 32, 32);
    this.sparkTexture = new THREE.CanvasTexture(c);
    this.sparkTexture.colorSpace = THREE.SRGBColorSpace;
  }

  // ── Frame update ───────────────────────────────────────────────────────────
  update(dt, input) {
    this.time += dt;
    this.cooldown = Math.max(0, this.cooldown - dt);

    if (this.recoilRecover > 0) {
      const recover = Math.min(this.recoilRecover, dt * 1.3);
      this.player.pitch = Math.min(1.45, this.player.pitch - recover);
      this.recoilRecover -= recover;
    }

    for (const t of this.targets) t.update(dt, this.player.position, this.time);

    // Weapon state. Reload can be cancelled by swapping focus; keep it simple.
    if (this.reloading) {
      this.reloadTimer += dt;
      if (this.reloadTimer >= C.weapon.reloadTime) {
        this.ammo = C.weapon.magazine;
        this.reloading = false;
        this.weapon.finishReload();
        this.audio.reloadEnd();
        this.hud?.setReload(false);
      }
    } else if (input.reloadPressed && this.ammo < C.weapon.magazine) {
      this._startReload();
    }

    if (this.enabled && input.fireHeld && !this.reloading && this.ammo > 0 && this.cooldown <= 0) {
      this._shoot();
    }

    // Empty click / auto-reload hint once.
    if (this.enabled && input.firePressed && this.ammo <= 0 && !this.reloading) {
      this._startReload();
      this.audio.dryFire();
    }

    this._updateEffects(dt);
    this.hud?.setAmmo(this.ammo, this.reloading ? this.reloadTimer / C.weapon.reloadTime : -1);
  }

  _startReload() {
    if (this.reloading) return;
    this.reloading = true;
    this.reloadTimer = 0;
    this.weapon.startReload();
    this.audio.reloadStart();
    this.hud?.setReload(true);
  }

  _shoot() {
    this.cooldown = C.weapon.fireInterval;
    this.ammo--;
    this.shots++;
    this.weapon.fire();
    this.audio.shot();

    // Spread reflects player state. Arcade, but movement still matters.
    const speed = this.player.horizontalSpeed;
    const spread = C.weapon.spreadStill +
      Math.min(1, speed / C.movement.sprintSpeed) * C.weapon.spreadMoving +
      (this.player.airborne ? C.weapon.spreadAir : 0);
    const dir = new THREE.Vector3();
    this.camera.getWorldDirection(dir);
    if (spread > 0) {
      dir.x += rand(-spread, spread);
      dir.y += rand(-spread, spread);
      dir.z += rand(-spread, spread) * .45;
      dir.normalize();
    }

    const origin = this.camera.getWorldPosition(new THREE.Vector3());
    this.raycaster.set(origin, dir);

    const liveHitboxes = [];
    for (const t of this.targets) if (!t.down) liveHitboxes.push(...t.hitboxes);
    const candidates = liveHitboxes.concat(this.world.hitMeshes);
    const intersections = this.raycaster.intersectObjects(candidates, false);
    const hit = intersections[0];

    // Muzzle endpoint, plus a tracer. The visual tracer starts at the barrel,
    // the gameplay ray starts at the camera: standard FPS convention.
    const muzzlePos = this.weapon.getMuzzleWorld(new THREE.Vector3());
    const end = hit ? hit.point.clone() : origin.clone().addScaledVector(dir, 90);
    this._spawnTracer(muzzlePos, end);

    if (hit) {
      if (hit.object.userData.target) {
        this.hits++;
        const target = hit.object.userData.target;
        const zone = hit.object.userData.zone;
        const damage = zone === 'head' ? C.weapon.damageHead : C.weapon.damageBody;
        const killed = target.hit(damage, zone);
        this._spawnSparks(hit.point, hit.face?.normal || new THREE.Vector3(0, 1, 0), '#ff4b28', 15);
        this._spawnImpactDecal(hit, true);
        this.audio.hit(zone === 'head');
        this.hud?.hit(zone === 'head', killed);
        if (killed) this._onKill(target, zone);
      } else {
        this._spawnSparks(hit.point, hit.face?.normal || new THREE.Vector3(0, 1, 0), '#ffd09a', 9);
        this._spawnImpactDecal(hit, false);
        this.audio.impact();
      }
    } else {
      this.audio.whiff();
    }

    // Camera kick (recovered over the next few frames).
    const pitchKick = C.weapon.recoilPitch * rand(.75, 1.35);
    this.player.pitch = Math.min(1.45, this.player.pitch + pitchKick);
    this.recoilRecover += pitchKick * .82;
    this.player.yaw += rand(-.5, .5) * C.weapon.recoilYaw;
    this.hud?.setAmmo(this.ammo, -1);
    this.onEvent('shot', { ammo: this.ammo });
  }

  _onKill(target, zone) {
    this.kills++;
    const points = zone === 'head' ? 250 : 100;
    this.score += points;
    this.audio.kill(zone === 'head');
    this._spawnSparks(target.root.position.clone().add(new THREE.Vector3(0, 1.2, 0)), new THREE.Vector3(0, 1, 0), '#ff7a2a', 28);
    this.hud?.kill(zone === 'head', points, this.kills);
    this.onEvent('kill', { points, headshot: zone === 'head', kills: this.kills, target });
  }

  // ── Effects ────────────────────────────────────────────────────────────────
  _spawnTracer(from, to) {
    const geo = new THREE.BufferGeometry().setFromPoints([from, to]);
    const mat = new THREE.LineBasicMaterial({
      color: 0xffd7a0, transparent: true, opacity: .85,
      blending: THREE.AdditiveBlending, depthWrite: false,
    });
    const line = new THREE.Line(geo, mat);
    line.renderOrder = 5;
    this.effects.add(line);
    this.tracers.push({ line, life: .075, max: .075 });
  }

  _spawnSparks(point, normal, color, count = 12) {
    const positions = new Float32Array(count * 3);
    const velocities = [];
    for (let i = 0; i < count; i++) {
      positions[i * 3] = point.x + rand(-.04, .04);
      positions[i * 3 + 1] = point.y + rand(-.04, .04);
      positions[i * 3 + 2] = point.z + rand(-.04, .04);
      const dir = normal.clone().multiplyScalar(rand(.8, 2.8));
      dir.x += rand(-2.4, 2.4); dir.y += rand(-.4, 2.7); dir.z += rand(-2.4, 2.4);
      velocities.push(dir);
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    const mat = new THREE.PointsMaterial({
      color: new THREE.Color(color), map: this.sparkTexture, size: .085,
      transparent: true, opacity: 1, depthWrite: false,
      blending: THREE.AdditiveBlending, sizeAttenuation: true,
    });
    const points = new THREE.Points(geo, mat);
    this.effects.add(points);
    this.sparks.push({ points, velocities, life: .42, max: .42 });
  }

  _spawnImpactDecal(hit, target) {
    const m = this.decalPool[this.decalIndex++ % this.decalPool.length];
    m.visible = true;
    m.position.copy(hit.point).addScaledVector(hit.face?.normal || new THREE.Vector3(0, 1, 0), .012);
    const normal = hit.face?.normal
      ? hit.face.normal.clone().applyMatrix3(_m3.getNormalMatrix(hit.object.matrixWorld)).normalize()
      : new THREE.Vector3(0, 1, 0);
    m.lookAt(_v.copy(m.position).add(normal));
    m.rotateZ(Math.random() * Math.PI * 2);
    const scale = target ? rand(.55, .95) : rand(.7, 1.3);
    m.scale.setScalar(scale);
    m.material = this.decalPool[0].material;
  }

  _updateEffects(dt) {
    for (let i = this.tracers.length - 1; i >= 0; i--) {
      const t = this.tracers[i];
      t.life -= dt;
      t.line.material.opacity = Math.max(0, t.life / t.max) * .85;
      if (t.life <= 0) {
        this.effects.remove(t.line);
        t.line.geometry.dispose(); t.line.material.dispose();
        this.tracers.splice(i, 1);
      }
    }

    for (let i = this.sparks.length - 1; i >= 0; i--) {
      const s = this.sparks[i];
      s.life -= dt;
      const arr = s.points.geometry.attributes.position.array;
      for (let j = 0; j < s.velocities.length; j++) {
        const v = s.velocities[j];
        arr[j * 3] += v.x * dt;
        arr[j * 3 + 1] += v.y * dt;
        arr[j * 3 + 2] += v.z * dt;
        v.y -= 8.8 * dt;
        v.multiplyScalar(1 - 1.9 * dt);
      }
      s.points.geometry.attributes.position.needsUpdate = true;
      s.points.material.opacity = Math.max(0, s.life / s.max);
      if (s.life <= 0) {
        this.effects.remove(s.points);
        s.points.geometry.dispose(); s.points.material.dispose();
        this.sparks.splice(i, 1);
      }
    }
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Angled, low-poly OPFOR dummy. Three body shots or one headshot neutralise it.
// It slides laterally on a rail and respawns, giving the arena a living rhythm.
// ─────────────────────────────────────────────────────────────────────────────
class TargetDummy {
  constructor(scene, anchor, index, audio) {
    this.scene = scene;
    this.anchor = anchor;
    this.index = index;
    this.audio = audio;
    this.hp = 100;
    this.down = false;
    this.downTimer = 0;
    this.hitFlash = 0;
    this.phase = anchor.phase;
    this.scaleIn = 1;
    this.hitboxes = [];
    this.materials = [];

    this.root = new THREE.Group();
    this.root.position.set(anchor.x, anchor.y, anchor.z);
    scene.add(this.root);

    const suit = new THREE.MeshStandardMaterial({ color: 0x2b2d28, roughness: .87, metalness: .08 });
    const armor = new THREE.MeshStandardMaterial({ color: 0x41453b, roughness: .62, metalness: .25 });
    const plate = new THREE.MeshStandardMaterial({ color: 0xb6481c, roughness: .58, metalness: .2, emissive: 0x2a0800, emissiveIntensity: 1 });
    const black = new THREE.MeshStandardMaterial({ color: 0x111310, roughness: .72, metalness: .3 });
    const visor = new THREE.MeshBasicMaterial({ color: 0xff421f });
    this.materials.push(suit, armor, plate, black);

    const add = (geo, mat, x, y, z, rx = 0, ry = 0, rz = 0) => {
      const m = new THREE.Mesh(geo, mat);
      m.position.set(x, y, z); m.rotation.set(rx, ry, rz);
      m.castShadow = true; m.receiveShadow = true;
      this.root.add(m); return m;
    };

    // Legs + boots.
    add(new THREE.BoxGeometry(.19, .74, .22), suit, -.16, .46, 0, 0, 0, .025);
    add(new THREE.BoxGeometry(.19, .74, .22), suit, .16, .46, 0, 0, 0, -.025);
    add(new THREE.BoxGeometry(.23, .12, .36), black, -.16, .06, -.03);
    add(new THREE.BoxGeometry(.23, .12, .36), black, .16, .06, -.03);
    add(new THREE.BoxGeometry(.22, .25, .25), armor, -.17, .77, 0);
    add(new THREE.BoxGeometry(.22, .25, .25), armor, .17, .77, 0);
    // Hips / belt.
    add(new THREE.BoxGeometry(.46, .2, .28), black, 0, .94, 0);
    add(new THREE.BoxGeometry(.5, .08, .3), plate, 0, .99, 0);
    // Torso.
    add(new THREE.BoxGeometry(.58, .62, .34), suit, 0, 1.26, 0);
    add(new THREE.BoxGeometry(.47, .37, .06), plate, 0, 1.3, .185);
    add(new THREE.BoxGeometry(.53, .12, .3), armor, 0, 1.5, 0);
    // Arms, slightly bent.
    add(new THREE.BoxGeometry(.17, .55, .2), suit, -.39, 1.22, 0, 0, 0, -.1);
    add(new THREE.BoxGeometry(.17, .2, .25), black, -.43, .98, .06, -.2, 0, -.1);
    add(new THREE.BoxGeometry(.17, .55, .2), suit, .39, 1.22, 0, 0, 0, .1);
    add(new THREE.BoxGeometry(.17, .2, .25), black, .43, .98, .06, -.2, 0, .1);
    // Neck / head / visor.
    add(new THREE.CylinderGeometry(.09, .1, .12, 8), black, 0, 1.63, 0);
    const head = add(new THREE.SphereGeometry(.18, 10, 8), armor, 0, 1.79, 0);
    head.scale.set(1, 1.05, .96);
    add(new THREE.BoxGeometry(.23, .07, .08), visor, 0, 1.82, .155);
    add(new THREE.BoxGeometry(.25, .05, .2), black, 0, 1.71, .01);
    // Chest lamp.
    add(new THREE.CircleGeometry(.035, 8), visor, 0, 1.36, .218);

    // A floating identity tick for readability against busy backgrounds.
    const tick = new THREE.Mesh(new THREE.PlaneGeometry(.34, .04), new THREE.MeshBasicMaterial({ color: 0xff5b1a, transparent: true, opacity: .75, side: THREE.DoubleSide }));
    tick.position.set(0, 2.11, 0); this.root.add(tick);
    this.tick = tick;

    // Hitboxes are invisible but raycastable. Head is a sphere; body a box.
    const hitMat = new THREE.MeshBasicMaterial({ visible: false });
    const bodyHit = new THREE.Mesh(new THREE.BoxGeometry(.62, 1.26, .46), hitMat);
    bodyHit.position.set(0, 1.07, 0);
    bodyHit.userData = { target: this, zone: 'body' };
    const headHit = new THREE.Mesh(new THREE.SphereGeometry(.23, 8, 6), hitMat);
    headHit.position.set(0, 1.8, 0);
    headHit.userData = { target: this, zone: 'head' };
    this.root.add(bodyHit, headHit);
    this.hitboxes.push(bodyHit, headHit);
    this.bodyHit = bodyHit;
    this.headHit = headHit;

    this.baseX = anchor.x;
    this.baseZ = anchor.z;
    this.root.rotation.y = Math.PI;
  }

  update(dt, playerPos, time) {
    if (this.down) {
      this.downTimer -= dt;
      this.root.rotation.z = damp(this.root.rotation.z, 1.45, 6, dt);
      this.root.position.y = damp(this.root.position.y, this.anchor.y - .2, 5, dt);
      if (this.downTimer <= 0) this.respawn();
      return;
    }

    this.scaleIn = damp(this.scaleIn, 1, 9, dt);
    this.root.scale.setScalar(Math.max(.01, this.scaleIn));
    this.root.rotation.z = damp(this.root.rotation.z, 0, 8, dt);

    // Lateral rail movement.
    const x = this.baseX + Math.sin(time * .62 + this.phase) * this.anchor.range;
    this.root.position.x = damp(this.root.position.x, x, 3.5, dt);
    this.root.position.y = this.anchor.y;
    // Face the player, with a tiny mechanical sway.
    const dx = playerPos.x - this.root.position.x;
    const dz = playerPos.z - this.root.position.z;
    const face = Math.atan2(dx, dz);
    let diff = face - this.root.rotation.y;
    while (diff > Math.PI) diff -= Math.PI * 2;
    while (diff < -Math.PI) diff += Math.PI * 2;
    this.root.rotation.y += diff * Math.min(1, dt * 2.2);
    this.root.rotation.z = Math.sin(time * 1.4 + this.phase) * .012;

    if (this.hitFlash > 0) {
      this.hitFlash -= dt;
      const k = Math.max(0, this.hitFlash / .12);
      for (const m of this.materials) {
        if (!m.emissive) continue;
        m.emissive.setRGB(k * .8, k * .15, k * .04);
        m.emissiveIntensity = 1 + k * 3;
      }
    } else {
      for (const m of this.materials) {
        if (!m.emissive) continue;
        m.emissiveIntensity = 1;
        m.emissive.setHex(m === this.materials[2] ? 0x2a0800 : 0x000000);
      }
    }

    const pulse = .7 + Math.sin(time * 3.2 + this.phase) * .18;
    this.tick.material.opacity = pulse;
    this.tick.lookAt(playerPos.x, this.tick.getWorldPosition(_v).y, playerPos.z);
  }

  hit(damage, zone) {
    if (this.down) return false;
    this.hp -= damage;
    this.hitFlash = .12;
    if (this.hp <= 0) {
      this.down = true;
      this.downTimer = 2.6;
      this.scaleIn = 1;
      return true;
    }
    return false;
  }

  respawn() {
    this.down = false;
    this.hp = 100;
    this.root.rotation.set(0, this.root.rotation.y, 0);
    this.root.position.y = this.anchor.y;
    this.scaleIn = .05;
    this.hitFlash = 0;
    this.bodyHit.visible = true;
    this.headHit.visible = true;
    this.audio?.respawn(this.index);
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Tiny synthesised sound engine. No samples, no loading, instant response.
// All voices are scheduled on the WebAudio clock to avoid main-thread jitter.
// ─────────────────────────────────────────────────────────────────────────────
export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.muted = false;
    this.noise = null;
    this.started = false;
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    const comp = this.ctx.createDynamicsCompressor();
    comp.threshold.value = -18; comp.knee.value = 18; comp.ratio.value = 5;
    comp.attack.value = .003; comp.release.value = .18;
    this.master = this.ctx.createGain();
    this.master.gain.value = .34;
    this.master.connect(comp).connect(this.ctx.destination);

    const len = this.ctx.sampleRate * 1.5;
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buf.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
    this.noise = buf;
    this._ambience();
    this.started = true;
  }

  setMuted(muted) {
    this.muted = muted;
    if (this.master) this.master.gain.setTargetAtTime(muted ? 0 : .34, this.ctx.currentTime, .03);
  }

  _ambience() {
    if (!this.ctx) return;
    // Wind bed.
    const src = this.ctx.createBufferSource();
    src.buffer = this.noise; src.loop = true;
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass'; filter.frequency.value = 340; filter.Q.value = .35;
    const gain = this.ctx.createGain(); gain.gain.value = .035;
    src.connect(filter).connect(gain).connect(this.master);
    src.start();
    // Electrical hum.
    const hum = this.ctx.createOscillator();
    hum.type = 'sine'; hum.frequency.value = 54;
    const humGain = this.ctx.createGain(); humGain.gain.value = .012;
    hum.connect(humGain).connect(this.master);
    hum.start();
  }

  _noise({ dur = .1, gain = .2, type = 'bandpass', freq = 1200, q = .8, delay = 0, pitch = 1 } = {}) {
    if (!this.ctx || this.muted) return;
    const t = this.ctx.currentTime + delay;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noise;
    src.playbackRate.value = pitch;
    const f = this.ctx.createBiquadFilter();
    f.type = type; f.frequency.setValueAtTime(freq, t); f.Q.value = q;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(gain, t);
    g.gain.exponentialRampToValueAtTime(.0001, t + dur);
    src.connect(f).connect(g).connect(this.master);
    src.start(t); src.stop(t + dur + .01);
  }

  _tone({ freq = 220, end = 70, dur = .12, gain = .15, type = 'sine', delay = 0 } = {}) {
    if (!this.ctx || this.muted) return;
    const t = this.ctx.currentTime + delay;
    const o = this.ctx.createOscillator();
    o.type = type;
    o.frequency.setValueAtTime(freq, t);
    o.frequency.exponentialRampToValueAtTime(Math.max(20, end), t + dur);
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(gain, t);
    g.gain.exponentialRampToValueAtTime(.0001, t + dur);
    o.connect(g).connect(this.master);
    o.start(t); o.stop(t + dur + .01);
  }

  shot() {
    this._noise({ dur: .11, gain: .58, type: 'bandpass', freq: 1550, q: .55, pitch: .92 });
    this._noise({ dur: .045, gain: .28, type: 'highpass', freq: 3400, q: .5 });
    this._tone({ freq: 145, end: 46, dur: .16, gain: .4, type: 'triangle' });
  }

  impact() { this._noise({ dur: .06, gain: .18, type: 'bandpass', freq: 2100, q: 1.2 }); }

  whiff() { this._noise({ dur: .09, gain: .07, type: 'highpass', freq: 3200, q: .4 }); }

  hit(head) {
    this._tone({ freq: head ? 1450 : 1120, end: head ? 980 : 760, dur: .055, gain: .14, type: 'square' });
    this._noise({ dur: .045, gain: .14, type: 'bandpass', freq: 2800, q: 2 });
  }

  kill(head) {
    this._tone({ freq: head ? 760 : 620, end: 980, dur: .08, gain: .12, type: 'triangle' });
    this._tone({ freq: 370, end: 260, dur: .17, gain: .12, type: 'sine', delay: .035 });
    this._noise({ dur: .22, gain: .18, type: 'lowpass', freq: 700, q: .6 });
  }

  reloadStart() {
    this._noise({ dur: .05, gain: .15, type: 'bandpass', freq: 1800, q: 2 });
    this._tone({ freq: 190, end: 120, dur: .06, gain: .12, type: 'square', delay: .05 });
  }

  reloadEnd() {
    this._noise({ dur: .045, gain: .2, type: 'bandpass', freq: 2300, q: 2 });
    this._tone({ freq: 260, end: 180, dur: .05, gain: .1, type: 'square', delay: .02 });
  }

  dryFire() { this._noise({ dur: .035, gain: .14, type: 'highpass', freq: 4200, q: .6 }); }

  slideStart() {
    this._noise({ dur: .38, gain: .14, type: 'bandpass', freq: 620, q: .5, pitch: .55 });
  }

  jump() {
    this._noise({ dur: .16, gain: .07, type: 'bandpass', freq: 780, q: .7, pitch: .7 });
    this._tone({ freq: 140, end: 90, dur: .1, gain: .05, type: 'sine' });
  }

  land(impact = 10) {
    const k = Math.min(1, impact / 16);
    this._noise({ dur: .11, gain: .16 * k, type: 'lowpass', freq: 420, q: .3 });
    this._tone({ freq: 78, end: 42, dur: .12, gain: .17 * k, type: 'sine' });
  }

  footstep() {
    this._noise({ dur: .055, gain: .075, type: 'bandpass', freq: 820 + Math.random() * 500, q: .7, pitch: .7 });
  }

  mantle() {
    this._noise({ dur: .14, gain: .1, type: 'bandpass', freq: 1050, q: .7, pitch: .8 });
    this._tone({ freq: 110, end: 70, dur: .14, gain: .08, type: 'triangle' });
  }

  mantleEnd() {
    this._noise({ dur: .08, gain: .07, type: 'lowpass', freq: 500, q: .3 });
  }

  respawn(index = 0) {
    this._tone({ freq: 660 + index * 24, end: 840 + index * 28, dur: .12, gain: .025, type: 'sine' });
  }

  uiClick() { this._tone({ freq: 560, end: 720, dur: .05, gain: .04, type: 'square' }); }
}

// ─────────────────────────────────────────────────────────────────────────────
// Thin DOM HUD. It only touches text nodes when values actually change, so the
// hot loop costs a handful of comparisons in the common case.
// ─────────────────────────────────────────────────────────────────────────────
export class HUD {
  constructor() {
    this.el = {
      start: document.getElementById('startScreen'),
      hud: document.getElementById('hud'),
      touch: document.getElementById('touchControls'),
      loading: document.getElementById('loading'),
      speed: document.getElementById('speed'),
      speedFill: document.getElementById('speedFill'),
      score: document.getElementById('score'),
      timer: document.getElementById('timer'),
      targetCount: document.getElementById('targetCount'),
      chipSprint: document.getElementById('chipSprint'),
      chipSlide: document.getElementById('chipSlide'),
      chipAir: document.getElementById('chipAir'),
      chipBhop: document.getElementById('chipBhop'),
      chipMantle: document.getElementById('chipMantle'),
      ammo: document.getElementById('ammo'),
      ammoFill: document.getElementById('ammoFill'),
      reload: document.getElementById('reloadLabel'),
      hitmarker: document.getElementById('hitmarker'),
      reticle: document.getElementById('reticleState'),
      compass: document.getElementById('compassDir'),
      mini: document.getElementById('miniPlayer'),
      feed: document.getElementById('eventFeed'),
      toast: document.getElementById('toast'),
      focus: document.getElementById('focusHint'),
    };
    this.last = {};
    this._toastTimer = 0;
    this._feed = 0;
    this._buildTicker();
  }

  _buildTicker() {
    const ticks = document.createElement('div');
    ticks.className = 'compass-ticks';
    this.el.compass.parentElement?.appendChild(ticks);
  }

  hideLoading() {
    this.el.loading.classList.add('is-out');
  }

  start(touch) {
    this.el.start.classList.add('is-out');
    this.el.hud.classList.remove('is-hidden');
    if (touch) this.el.touch.classList.remove('is-hidden');
    else this.el.touch.classList.add('is-hidden');
    document.body.classList.add('playing');
  }

  setLocked(locked) {
    this.el.focus.classList.toggle('hide', locked);
  }

  // ── Per-frame readout ──────────────────────────────────────────────────────
  update(player, dt) {
    const speed = player.horizontalSpeed;
    const speedText = speed.toFixed(1).padStart(4, '0');
    if (speedText !== this.last.speed) {
      this.el.speed.textContent = speedText;
      this.last.speed = speedText;
    }
    this.el.speedFill.style.width = `${Math.min(100, speed / 22.5 * 100)}%`;

    bodyState('is-fast', speed > 12.2);
    bodyState('is-sliding', player.sliding);
    bodyState('is-firing', player._firing || false);

    this.el.chipSprint.classList.toggle('on', player.sprinting);
    this.el.chipSlide.classList.toggle('on', player.sliding);
    this.el.chipAir.classList.toggle('on', player.airborne);
    this.el.chipBhop.classList.toggle('on', player.grounded && speed > 13.2);
    this.el.chipMantle.classList.toggle('on', player.mantling);

    let state = 'PRONTO';
    if (player.mantling) state = 'MANTLE';
    else if (player.sliding) state = 'SLIDE INFINITO';
    else if (player.airborne) state = speed > 12 ? 'AIR STRAFE' : 'NO AR';
    else if (player.sprinting) state = 'SPRINT';
    else if (speed > 1) state = 'EM MOVIMENTO';
    if (state !== this.last.state) { this.el.reticle.textContent = state; this.last.state = state; }

    const heading = ((-player.yaw * 180 / Math.PI) % 360 + 360) % 360;
    const dirs = ['N', 'NE', 'L', 'SE', 'S', 'SO', 'O', 'NO'];
    const dir = dirs[Math.round(heading / 45) % 8];
    if (dir !== this.last.dir) { this.el.compass.textContent = dir; this.last.dir = dir; }
    this.el.mini.style.transform = `translate(-50%,-50%) rotate(${-player.yaw}rad)`;

    // Speed-reactive lens: not a filter, just a CSS overlay.
    const lens = document.querySelector('.speedlines');
    if (lens) lens.style.opacity = speed > 13.5 ? `${Math.min(.75, (speed - 13.5) / 7 + .2)}` : '0';
  }

  setAmmo(ammo, reloadProgress) {
    if (ammo !== this.last.ammo) {
      this.el.ammo.textContent = String(ammo).padStart(2, '0');
      this.el.ammoFill.style.width = `${Math.max(0, ammo / 30 * 100)}%`;
      this.el.ammoFill.style.background = ammo <= 7 ? 'var(--orange)' : 'var(--paper)';
      this.last.ammo = ammo;
    }
    if (reloadProgress >= 0) {
      const pct = Math.round(reloadProgress * 100);
      const txt = `RECARREGANDO ${String(pct).padStart(2, '0')}%`;
      if (txt !== this.last.reload) { this.el.reload.textContent = txt; this.last.reload = txt; }
      this.el.reload.classList.add('is-reloading');
    } else {
      if (this.last.reload !== 'idle') {
        this.el.reload.textContent = 'R — RECARREGAR';
        this.el.reload.classList.remove('is-reloading');
        this.last.reload = 'idle';
      }
    }
  }

  setReload(active) {
    if (!active) this.el.reload.classList.remove('is-reloading');
  }

  setScore(score, kills, seconds) {
    const ss = String(score).padStart(4, '0');
    if (ss !== this.last.score) { this.el.score.textContent = ss; this.last.score = ss; }
    const kk = String(kills).padStart(2, '0');
    if (kk !== this.last.kills) { this.el.targetCount.textContent = kk; this.last.kills = kk; }
    const t = `${String(Math.floor(seconds / 60)).padStart(2, '0')}:${String(Math.floor(seconds % 60)).padStart(2, '0')}`;
    if (t !== this.last.timer) { this.el.timer.textContent = t; this.last.timer = t; }
  }

  hit(head, kill) {
    const h = this.el.hitmarker;
    h.classList.remove('show', 'kill');
    // Force a reflow so consecutive shots retrigger the CSS animation.
    void h.offsetWidth;
    if (kill) h.classList.add('kill');
    h.classList.add('show');
    if (kill) this.toast(head ? 'HEADSHOT <b>+250</b>' : 'ALVO NEUTRALIZADO <b>+100</b>', 900);
    else if (head) this.toast('HEADSHOT', 500);
  }

  kill(head, points, total) {
    this.pushEvent(head ? 'HEADSHOT' : 'ALVO NEUTRALIZADO', `+${points}`, total);
    if (total === 12) {
      setTimeout(() => this.toast('DRILL COMPLETO <b>// 12 ALVOS</b>', 2600), 700);
    }
  }

  pushEvent(label, value = '', n = null) {
    const div = document.createElement('div');
    div.className = 'event';
    div.innerHTML = `${n !== null ? `<i>#${String(n).padStart(2, '0')}</i>` : ''}<span>${label}</span>${value ? `<b>${value}</b>` : ''}`;
    this.el.feed.appendChild(div);
    while (this.el.feed.children.length > 5) this.el.feed.firstChild.remove();
    this._feed++;
    setTimeout(() => { div.style.opacity = '0'; div.style.transition = 'opacity .3s'; setTimeout(() => div.remove(), 320); }, 2800);
  }

  toast(html, ms = 900) {
    const t = this.el.toast;
    t.innerHTML = html;
    t.classList.add('show');
    clearTimeout(this._toastTimer);
    this._toastTimer = setTimeout(() => t.classList.remove('show'), ms);
  }

  flashDamage() {
    // Reserved for future enemies; kept here so the HUD remains self-contained.
    document.body.animate?.(
      [{ boxShadow: 'inset 0 0 0 rgba(255,40,20,0)' }, { boxShadow: 'inset 0 0 120px rgba(255,40,20,.55)' }, { boxShadow: 'inset 0 0 0 rgba(255,40,20,0)' }],
      { duration: 280, easing: 'ease-out' }
    );
  }
}

function bodyState(cls, on) {
  if (document.body.classList.contains(cls) !== on) document.body.classList.toggle(cls, on);
}

import * as THREE from 'three';
import { CONFIG, isTouchDevice } from './config.js';
import { Input } from './input.js';
import { HUD } from './hud.js';
import { AudioEngine } from './audio.js';
import { buildWorld } from './world.js';
import { PlayerController } from './player.js';
import { Weapon } from './weapon.js';
import { Combat } from './combat.js';

// ─────────────────────────────────────────────────────────────────────────────
// COMBAT//SHIFT — arena de movimento
// Fixed 120 Hz simulation, render-rate-independent animation, instant input.
// ─────────────────────────────────────────────────────────────────────────────
const STEP = 1 / 120;

class Game {
  constructor() {
    this.canvas = document.getElementById('game');
    this.started = false;
    this.startTime = 0;
    this.gameTime = 0;
    this.accumulator = 0;
    this.clock = new THREE.Clock();
    this.stepDistance = 0;
    this.muted = false;
    this.introTime = 0;

    this._initRenderer();
    this._initScene();
    this._initInput();
    this._initGame();
    this._bindUI();
    this._bindResize();

    this.hud.hideLoading();
    this.renderer.setAnimationLoop(() => this._frame());
    this._exposeDebug();
  }

  _initRenderer() {
    this.renderer = new THREE.WebGLRenderer({
      canvas: this.canvas,
      antialias: true,
      powerPreference: 'high-performance',
      stencil: false,
      alpha: false,
    });
    this.renderer.setPixelRatio(Math.min(devicePixelRatio || 1, isTouchDevice() ? 1.35 : 1.6));
    this.renderer.setSize(innerWidth, innerHeight, false);
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.04;
    this.renderer.shadowMap.enabled = true;
    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  }

  _initScene() {
    this.scene = new THREE.Scene();
    this.scene.fog = new THREE.FogExp2(0xb9946d, .0072);
    this.scene.background = new THREE.Color(0xb9946d);
    this.camera = new THREE.PerspectiveCamera(79, innerWidth / innerHeight, .022, 240);
    this.camera.rotation.order = 'YXZ';
    this.scene.add(this.camera);

    this.world = buildWorld(this.scene, this.renderer);
    this.player = new PlayerController(this.camera, this.world);
    this.audio = new AudioEngine();
    this.hud = new HUD();
    this.weapon = new Weapon(this.camera, this.renderer);
    this.weapon.hide();

    this.combat = new Combat({
      scene: this.scene,
      camera: this.camera,
      world: this.world,
      player: this.player,
      weapon: this.weapon,
      audio: this.audio,
      hud: this.hud,
      onEvent: (name, data) => this._onCombatEvent(name, data),
    });
    this.combat.enabled = false;
  }

  _initInput() {
    this.input = new Input(this.canvas);
    this.input.onLockChange = (locked) => {
      this.hud.setLocked(locked);
      if (locked) document.body.classList.add('locked');
      else document.body.classList.remove('locked');
    };
  }

  _initGame() {
    // Intro camera: a slow, low crane shot behind the start screen.
    this._introCam = { pos: new THREE.Vector3(5.4, 2.1, 20.5), look: new THREE.Vector3(-4, 1.9, -5) };
    this.camera.position.copy(this._introCam.pos);
    this.camera.fov = 64;
    this.camera.updateProjectionMatrix();
    this.camera.lookAt(this._introCam.look);
  }

  _bindUI() {
    const btn = document.getElementById('startButton');
    btn.addEventListener('click', (e) => {
      e.preventDefault();
      this.start();
    });

    // Mobile buttons live outside the canvas, so prevent the page from panning.
    for (const el of document.querySelectorAll('.touch-btn, .stick-base')) {
      el.addEventListener('touchstart', (e) => e.preventDefault(), { passive: false });
    }

    addEventListener('keydown', (e) => {
      if (e.code === 'KeyM') {
        this.muted = !this.muted;
        this.audio.setMuted(this.muted);
        this.hud.toast(this.muted ? 'ÁUDIO <b>OFF</b>' : 'ÁUDIO <b>ON</b>', 700);
      }
    });
  }

  start() {
    if (this.started) return;
    this.started = true;
    this.startTime = performance.now() / 1000;
    this.audio.init();
    this.audio.uiClick();
    this.input.enabled = true;
    this.combat.enabled = true;
    this.weapon.show();
    this.hud.start(this.input.touch);
    this.hud.setLocked(false);
    document.body.classList.add('playing');
    if (!this.input.touch) this.input.requestLock();
    this.player.reset();
    this.player.pitch = 0;
    this.player.yaw = 0;
    this.camera.fov = CONFIG.camera.baseFov;
    this.hud.toast('MOVA-SE <b>//</b> NÃO PARE', 1300);
    setTimeout(() => this.hud.toast('SEGURE <b>CTRL</b> PARA SLIDE INFINITO', 1600), 1450);
    this._updateCameraImmediate();
  }

  _bindResize() {
    const resize = () => {
      this.camera.aspect = innerWidth / innerHeight;
      this.camera.updateProjectionMatrix();
      this.renderer.setPixelRatio(Math.min(devicePixelRatio || 1, isTouchDevice() ? 1.35 : 1.6));
      this.renderer.setSize(innerWidth, innerHeight, false);
    };
    addEventListener('resize', resize);
    addEventListener('orientationchange', () => setTimeout(resize, 120));
  }

  // ── Main loop ──────────────────────────────────────────────────────────────
  _frame() {
    const rawDt = this.clock.getDelta();
    const dt = Math.min(rawDt, .05);

    if (this.started) {
      // Mouse look is applied once per rendered frame; physics may step twice.
      if (this.input.lookX || this.input.lookY) {
        this.player.addLook(this.input.lookX, this.input.lookY);
        this.input.lookX = 0; this.input.lookY = 0;
      }

      this.accumulator += dt;
      let steps = 0;
      while (this.accumulator >= STEP && steps < 6) {
        this.player.update(STEP, this.input);
        this.combat.update(STEP, this.input);
        this.accumulator -= STEP;
        steps++;
        this._drainPlayerEvents();
      }
      if (steps === 0) this._drainPlayerEvents();
      if (steps === 6) this.accumulator = 0;

      this.gameTime = performance.now() / 1000 - this.startTime;
      this.player._firing = this.input.fireHeld && !this.combat.reloading;
      this.weapon.update(dt, this.player, this.player._firing);
      this.hud.update(this.player, dt);
      this.hud.setScore(this.combat.score, this.combat.kills, this.gameTime);
      this._updateFootsteps(dt);
    } else {
      // Live world behind the menu, but no player simulation.
      this.introTime += dt;
      this.camera.position.x = this._introCam.pos.x + Math.sin(this.introTime * .09) * .22;
      this.camera.position.y = this._introCam.pos.y + Math.sin(this.introTime * .13) * .035;
      this.camera.lookAt(
        this._introCam.look.x,
        this._introCam.look.y + Math.sin(this.introTime * .1) * .05,
        this._introCam.look.z
      );
      this.world.update(dt, this.introTime);
    }

    this.renderer.render(this.scene, this.camera);
    this.input.endFrame();
  }

  _drainPlayerEvents() {
    if (!this.player.events.length) return;
    for (const ev of this.player.events) {
      switch (ev.name) {
        case 'jump':
          this.audio.jump();
          break;
        case 'slideStart':
          this.audio.slideStart();
          this.hud.pushEvent('SLIDE INFINITO', `${ev.data.toFixed(1)} M/S`);
          break;
        case 'slideJump':
          this.audio.jump();
          this.hud.pushEvent('SLIDE JUMP', 'MOMENTO PRESERVADO');
          break;
        case 'land':
          if (ev.data > 7) this.audio.land(ev.data);
          if (ev.data > 6 && this.player.horizontalSpeed > 13) {
            this.hud.pushEvent('BHOP', `${this.player.horizontalSpeed.toFixed(1)} M/S`);
          }
          break;
        case 'mantle':
          this.audio.mantle();
          this.hud.pushEvent('AUTO MANTLE', 'VAULT RÁPIDO');
          break;
        case 'mantleEnd':
          this.audio.mantleEnd();
          break;
        default:
          break;
      }
    }
    this.player.events.length = 0;
  }

  _updateFootsteps(dt) {
    if (!this.player.grounded || this.player.sliding || this.player.horizontalSpeed < 1.2) {
      this.stepDistance = 0;
      return;
    }
    this.stepDistance += this.player.horizontalSpeed * dt;
    const stride = 2.35 + Math.min(1, this.player.horizontalSpeed / 20) * 1.0;
    const speed = this.player.horizontalSpeed;
    if (this.stepDistance > stride) {
      this.stepDistance = 0;
      this.audio.footstep();
      if (speed > 12.5) this.hud.pushEvent('FLOW STATE', `${speed.toFixed(1)} M/S`);
    }
  }

  _onCombatEvent(name) {
    if (name === 'kill') {
      // Already surfaced through HUD; kept as a hook for future game modes.
    }
  }

  _updateCameraImmediate() {
    this.camera.position.set(this.player.position.x, this.player.position.y + this.player.eyeHeight, this.player.position.z);
    this.camera.rotation.set(this.player.pitch, this.player.yaw, 0);
    this.camera.fov = this.player.fov;
    this.camera.updateProjectionMatrix();
  }

  // A tiny test surface for automated checks and curious players.
  _exposeDebug() {
    const game = this;
    window.COMBAT_SHIFT = {
      game,
      get state() {
        return {
          started: game.started,
          position: game.player.position.toArray(),
          velocity: game.player.velocity.toArray(),
          speed: game.player.horizontalSpeed,
          grounded: game.player.grounded,
          sliding: game.player.sliding,
          sprinting: game.player.sprinting,
          airborne: game.player.airborne,
          mantling: game.player.mantling,
          fov: game.camera.fov,
          yaw: game.player.yaw,
          score: game.combat.score,
          kills: game.combat.kills,
          ammo: game.combat.ammo,
          targets: game.combat.targets.length,
        };
      },
      teleport(x, z, y = 0) {
        game.player.position.set(x, y, z);
        game.player.velocity.set(0, 0, 0);
        game.player.grounded = true;
      },
      look(yaw, pitch = 0) {
        game.player.yaw = yaw;
        game.player.pitch = pitch;
      },
      press(code, ms = 200) {
        const down = new KeyboardEvent('keydown', { code, bubbles: true });
        const up = new KeyboardEvent('keyup', { code, bubbles: true });
        window.dispatchEvent(down);
        setTimeout(() => window.dispatchEvent(up), ms);
      },
      fire(ms = 80) {
        game.input.fireHeld = true;
        game.input.firePressed = true;
        setTimeout(() => { game.input.fireHeld = false; }, ms);
      },
    };
  }
}

// Wait for the display face before building canvas labels, then start.
async function boot() {
  try {
    if (document.fonts?.ready) await document.fonts.ready;
    new Game();
  } catch (error) {
    console.error(error);
    const loading = document.getElementById('loading');
    if (loading) {
      loading.innerHTML = `<div class="loading-mark" style="font-size:30px">ERRO DE RENDERIZAÇÃO</div><span>${error.message}</span>`;
    }
  }
}

boot();

