55:     this.speed = 0;
56:     this.horizontalSpeed = 0;
57:     this.airTime = 0;
58:     this.groundTime = 0;
59:     this.coyote = 0;
60:     this.jumpBuffer = 0;
61:     this.mantleCooldown = 0;
62:     this.lastGrounded = true;
63:     this.wasSliding = false;
64:     this.bhopChain = 0;
65:     this.slideTime = 0;
66:     this.events = [];
67: 
68:     this._mantle = null;
69:     this._wallHit = null;
70:     this._prevPosition = this.position.clone();
71:     this._slideDir = new THREE.Vector2(0, -1);
72:     this._baseYaw = this.yaw;
73:   }
74: 
75:   reset() {
76:     this.position.set(C.arena.spawn.x, C.arena.spawn.y, C.arena.spawn.z);
77:     this.velocity.set(0, 0, 0);
78:     this.yaw = 0; this.pitch = 0;
79:     this.grounded = true; this.sliding = false; this.crouching = false;
80:     this.mantling = false; this.airborne = false; this.speed = 0;
81:     this.eyeHeight = C.player.eyeStanding;
82:     this._mantle = null;
83:   }
84: 
85:   emit(name, data = null) {
86:     this.events.push({ name, data });
87:   }
88: 
89:   addLook(dx, dy) {
90:     this.yaw -= dx * C.camera.mouseSensitivity;
91:     this.pitch -= dy * C.camera.mouseSensitivity;
92:     this.pitch = clamp(this.pitch, -C.camera.pitchLimit, C.camera.pitchLimit);
93:     // Keep yaw bounded to avoid precision loss after very long sessions.
94:     if (this.yaw > Math.PI) this.yaw -= Math.PI * 2;
95:     if (this.yaw < -Math.PI) this.yaw += Math.PI * 2;
96:   }
97: 
98:   get forward() {
99:     _forward.set(-Math.sin(this.yaw), 0, -Math.cos(this.yaw));
100:     return _forward;
101:   }
102: 
103:   get speedRatio() {
104:     return clamp((this.horizontalSpeed - 4) / (C.movement.sprintSpeed - 4), 0, 1.35);
105:   }
106: 
107:   // ── Core step, called at a fixed 120 Hz ─────────────────────────────────────
108:   update(dt, input) {
109:     this._prevPosition.copy(this.position);
110:     this.lastGrounded = this.grounded;
111:     this.justLanded = false;
112:     this._jumpHeld = input.jumpHeld;
113:     this.mantleCooldown = Math.max(0, this.mantleCooldown - dt);
114:     this.jumpBuffer = Math.max(0, this.jumpBuffer - dt);
115: 
116:     if (this.mantling) {
117:       this._updateMantle(dt);
118:       this._updateCamera(dt);
119:       return;
120:     }
121: 
122:     if (input.jumpPressed) this.jumpBuffer = C.movement.jumpBufferTime;
123:     const wish = this._wishDirection(input);
124:     const wishLen = Math.hypot(wish.x, wish.z);
125: 
126:     // Crouch / slide intent. Entry is automatic while carrying speed.
127:     this._updateCrouchState(input);
128: 
129:     // ── Jump / bunny hop ─────────────────────────────────────────────────────
130:     const canJump = this.grounded || this.coyote > 0;
131:     if ((this.jumpBuffer > 0 || (input.jumpHeld && this.grounded)) && canJump) {
132:       if (!this._tryMantle(input, true)) {
133:         this._jump(input);
134:       }
135:       this.jumpBuffer = 0;
136:     }
137: 
138:     if (this.mantling) {
139:       this._updateCamera(dt);
140:       return;
141:     }
142: 
143:     // ── Horizontal locomotion ───────────────────────────────────────────────
144:     if (this.sliding && this.grounded) {
145:       this._updateSlide(dt, input);
146:     } else if (this.grounded) {
147:       this._updateGround(dt, wish, wishLen, input);
148:     } else {
149:       this._updateAir(dt, wish, wishLen);
150:     }
151: 
152:     // ── Integrate + collide ─────────────────────────────────────────────────
153:     this._moveHorizontal(this.velocity.x * dt, this.velocity.z * dt);
154:     this._moveVertical(dt);
155: 
156:     // Mantle can trigger mid-air when the player carries momentum into a ledge.
157:     if (!this.grounded && !this.mantling && this.mantleCooldown <= 0 && this.airTime > 0.05) {
158:       const intoLedge = this._wallHit && this.forward.dot(_tmp.set(this.velocity.x, 0, this.velocity.z).normalize()) > 0.3;
159:       if (intoLedgeGuard(this.velocity, this.forward) || intoLedge) {
160:         this._tryMantle(input, false);
161:       }
162:     }
163: 
164:     this._updateTimers(dt);
165:     this._updateCamera(dt);
166: 
167:     this.horizontalSpeed = Math.hypot(this.velocity.x, this.velocity.z);
168:     this.speed = this.horizontalSpeed;
169:     if (this.horizontalSpeed > C.movement.sprintSpeed + 0.5 && !this.sliding) this.bhopChain = Math.max(this.bhopChain, 1);
170:   }
171: 
172:   _updateTimers(dt) {
173:     if (this.grounded) {
174:       this.airTime = 0;
175:       this.groundTime += dt;
176:       this.coyote = C.movement.coyoteTime;
177:       if (this.sliding) this.slideTime += dt;
178:     } else {
179:       this.airTime += dt;
180:       this.groundTime = 0;
181:       this.coyote = Math.max(0, this.coyote - dt);
182:     }
183:     this.airborne = !this.grounded && !this.mantling;
184:   }
185: 
186:   _wishDirection(input) {
187:     const f = this.forward;
188:     _wish.set(
189:       f.x * input.moveY - f.z * input.moveX,
190:       0,
191:       f.z * input.moveY + f.x * input.moveX
192:     );
193:     const len = _wish.length();
194:     if (len > 1) _wish.multiplyScalar(1 / len);
195:     return _wish;
196:   }
197: 
198:   _updateCrouchState(input) {
199:     const wantsCrouch = input.crouchHeld;
200:     const speed = Math.hypot(this.velocity.x, this.velocity.z);
201: 
202:     if (wantsCrouch && !this.sliding && this.grounded && speed >= C.slide.minEntrySpeed) {
203:       this._startSlide(speed);
204:     }
205: 
206:     if (wantsCrouch && !this.sliding) {
207:       this.crouching = true;
208:       this.height = C.player.crouchHeight;
209:     }
210: 
211:     if (!wantsCrouch && this.sliding) {
212:       if (this._canStand()) {
213:         this.sliding = false;
214:         this.crouching = false;
215:         this.height = this.standingHeight;
216:         this.emit('slideEnd');
217:       }
218:     }
219: 
220:     if (!wantsCrouch && !this.sliding && this.crouching) {
221:       if (this._canStand()) {
222:         this.crouching = false;
223:         this.height = this.standingHeight;
224:       }
225:     }
226: 
227:     if (this.sliding) {
228:       this.crouching = true;
229:       this.height = C.player.crouchHeight;
230:     }
231:   }
232: 
233:   _startSlide(speed) {
234:     this.sliding = true;
235:     this.crouching = true;
236:     this.height = C.player.crouchHeight;
237:     this.slideTime = 0;
238:     this.wasSliding = true;
239:     const dir = new THREE.Vector2(this.velocity.x, this.velocity.z);
240:     if (dir.lengthSq() < 0.01) dir.set(-Math.sin(this.yaw), -Math.cos(this.yaw));
241:     dir.normalize();
242:     this._slideDir.copy(dir);
243:     const boosted = Math.min(C.slide.maxSpeed, speed * C.slide.entryBoost);
244:     this.velocity.x = dir.x * boosted;
245:     this.velocity.z = dir.y * boosted;
246:     this.emit('slideStart', boosted);
247:   }
248: 
249:   _updateSlide(dt, input) {
250:     const speed = Math.hypot(this.velocity.x, this.velocity.z);
251:     if (speed < 1.2) {
252:       this.sliding = false;
253:       this.crouching = input.crouchHeld;
254:       this.height = this.crouching ? C.player.crouchHeight : this.standingHeight;
255:       return;
256:     }
257: 
258:     // The slide has no duration timer. It only bleeds an almost imperceptible
259:     // amount of speed so a good line still feels like it stores momentum.
260:     let newSpeed = Math.min(C.slide.maxSpeed, speed * (1 - C.slide.drag * dt));
261: 
262:     // Steer the velocity vector, not the camera. A 180° look becomes a 180°
263:     // velocity turn at a fixed angular rate while speed stays constant.
264:     this._slideDir.set(this.velocity.x / speed, this.velocity.z / speed);
265:     const f = this.forward;
266:     const targetAngle = Math.atan2(f.x, f.z) + input.moveX * 0.38;
267:     const currentAngle = Math.atan2(this._slideDir.x, this._slideDir.y);
268:     let delta = targetAngle - currentAngle;
269:     while (delta > Math.PI) delta -= Math.PI * 2;
270:     while (delta < -Math.PI) delta += Math.PI * 2;
271:     const turn = clamp(delta, -C.slide.turnRate * dt, C.slide.turnRate * dt);
272:     const newAngle = currentAngle + turn;
273:     this._slideDir.set(Math.sin(newAngle), Math.cos(newAngle));
274: 
275:     this.velocity.x = this._slideDir.x * newSpeed;
276:     this.velocity.z = this._slideDir.y * newSpeed;
277:     this._slideTurn = turn / Math.max(dt, 0.0001);
278:   }
279: 
280:   _updateGround(dt, wish, wishLen, input) {
281:     const speed = Math.hypot(this.velocity.x, this.velocity.z);
282:     const crouching = this.crouching || this.sliding;
283:     this.sprinting = !crouching && input.sprintHeld && input.moveY > 0.15;
284: 
285:     // Ground friction: high enough to feel snappy, low enough to preserve a
286:     // post-slide flow state. While holding a direction we use a lighter drag,
287:     // otherwise acceleration and friction would settle below sprint speed.
288:     if (speed > 0) {
289:       const friction = wishLen > 0.05 ? 3.2 : C.movement.groundFriction;
290:       const drop = Math.max(speed, C.movement.stopSpeed) * friction * dt;
291:       const newSpeed = Math.max(0, speed - drop) / speed;
292:       this.velocity.x *= newSpeed;
293:       this.velocity.z *= newSpeed;
294:     }
295: 
296:     const targetSpeed = crouching ? 4.2 : (this.sprinting ? C.movement.sprintSpeed : C.movement.walkSpeed);
297:     this._accelerate(wish, wishLen, targetSpeed, C.movement.groundAcceleration, dt);
298:   }
299: 
300:   _updateAir(dt, wish, wishLen) {
301:     this.crouching = false;
302:     this.sprinting = false;
303:     this.height = this.standingHeight;
304: 
305:     // Quake air acceleration. The projection means holding a strafe key can
306:     // bend the trajectory and even gain a little speed, but never scrubs it.
307:     if (wishLen > 0.01) {
308:       const projected = this.velocity.x * wish.x + this.velocity.z * wish.z;
309:       const add = C.movement.airWishSpeed - projected;
310:       if (add > 0) {
311:         const accel = Math.min(C.movement.airAcceleration * dt, add);
312:         this.velocity.x += wish.x * accel;
313:         this.velocity.z += wish.z * accel;
314:       } else {
315:         // At high speed, nudge the vector toward the input without changing
316:         // magnitude. This is the "no deceleration" part of the brief.
317:         const vx = this.velocity.x, vz = this.velocity.z;
318:         const speed = Math.hypot(vx, vz);
319:         if (speed > 1) {
320:           const steer = Math.min(1, dt * C.movement.airSteerRate);
321:           let nx = vx / speed + wish.x * steer * 0.14;
322:           let nz = vz / speed + wish.z * steer * 0.14;
323:           const nl = Math.hypot(nx, nz) || 1;
324:           nx /= nl; nz /= nl;
325:           this.velocity.x = nx * speed;
326:           this.velocity.z = nz * speed;
327:         }
328:       }
329:     }
330: 
331:     // Preserve the boost, but prevent runaway acceleration.
332:     const hs = Math.hypot(this.velocity.x, this.velocity.z);
333:     if (hs > C.movement.maxAirSpeed) {
334:       const s = C.movement.maxAirSpeed / hs;
335:       this.velocity.x *= s;
336:       this.velocity.z *= s;
337:     }
338:   }
339: 
340:   _accelerate(wish, wishLen, targetSpeed, accel, dt) {
341:     if (wishLen < 0.01) return;
342:     const projected = this.velocity.x * wish.x + this.velocity.z * wish.z;
343:     const add = targetSpeed - projected;
344:     if (add <= 0) return;
345:     const amount = Math.min(accel * dt, add);
346:     this.velocity.x += wish.x * amount;
347:     this.velocity.z += wish.z * amount;
348:   }
349: 
350:   _jump(input) {
351:     const wasSliding = this.sliding;
352:     const slideSpeed = Math.hypot(this.velocity.x, this.velocity.z);
353:     this.velocity.y = C.movement.jumpSpeed;
354:     if (wasSliding && slideSpeed > 0) {
355:       // Slide-jump keeps almost all momentum and adds a tiny exit boost.
356:       const s = Math.min(C.slide.maxSpeed, slideSpeed * C.slide.jumpBoost) / slideSpeed;
357:       this.velocity.x *= s;
358:       this.velocity.z *= s;
359:     }
360:     this.sliding = false;
361:     this.crouching = false;
362:     this.height = this.standingHeight;
363:     this.grounded = false;
364:     this.coyote = 0;
365:     this.justLanded = false;
366:     this.emit(wasSliding ? 'slideJump' : 'jump', slideSpeed);
367:   }
368: 
369:   _updateVertical(dt) {
370:     if (this.grounded) {
371:       // Snap to steps and ramps while staying glued to the floor.
372:       const support = this._groundHeight(this.position.x, this.position.z, this.position.y + C.player.stepHeight + 0.08);
373:       if (support > -Infinity && this.position.y - support <= 0.48 && support <= this.position.y + C.player.stepHeight + 0.02) {
374:         this.position.y = support;
375:         this.velocity.y = 0;
376:       } else if (support > -Infinity && this.position.y - support > 0.49) {
377:         this.grounded = false;
378:       }
379:       if (this.grounded) return;
380:     }
381: 
382:     const oldY = this.position.y;
383:     this.velocity.y -= C.movement.gravity * dt;
384:     this.position.y += this.velocity.y * dt;
385: 
386:     const support = this._groundHeight(this.position.x, this.position.z, oldY + 0.04);
387:     if (this.velocity.y <= 0 && this.position.y <= support) {
388:       const impact = Math.abs(this.velocity.y);
389:       this.position.y = support;
390:       this.velocity.y = 0;
391:       this.grounded = true;
392:       this.justLanded = true;
393:       this.landDip = Math.min(0.13, impact * 0.009);
394:       this.landSpring = impact;
395:       this.emit('land', impact);
396: 
397:       // Auto-bhop: hold jump and the next physics step immediately launches.
398:       if (this.jumpBuffer > 0 || (this.grounded && this._jumpHeld)) {
399:         this.jumpBuffer = 0;
400:         this._bhopRequested = true;
401:       }
402:     } else {
403:       this.grounded = false;
404: 
405:       // Ceiling collision. Handles the low container underpass.
406:       const head = this.position.y + this.height;
407:       for (const { box } of this.world.colliders) {
408:         if (!this._circleOverlap(box, this.position.x, this.position.z, this.radius * 0.9)) continue;
409:         if (box.min.y < head && box.min.y >= oldY + this.height - 0.05) {
410:           if (this.velocity.y > 0) {
411:             this.position.y = box.min.y - this.height;
412:             this.velocity.y = 0;
413:           }
414:         }
415:       }
416:     }
417:   }
418: 
419:   _moveVertical(dt) {
420:     // Jump requests coming from the landing branch or the held-jump bhop.
421:     if (this._bhopRequested) {
422:       this._bhopRequested = false;
423:       if (!this._tryMantle(null, false)) this._jump(null);
424:     }
425:     this._updateVertical(dt);
426:   }
427: 
428:   _moveHorizontal(dx, dz) {
429:     this._wallHit = null;
430:     this.position.x += dx;
431:     this._resolveAxis('x', dx);
432:     this.position.z += dz;
433:     this._resolveAxis('z', dz);
434: 
435:     const limit = C.arena.halfSize - 0.7;
436:     this.position.x = clamp(this.position.x, -limit, limit);
437:     this.position.z = clamp(this.position.z, -limit, limit);
438:   }
439: 
440:   _resolveAxis(axis, delta) {
441:     if (Math.abs(delta) < 0.00001) return;
442:     const r = this.radius;
443:     for (const { box } of this.world.colliders) {
444:       if (!this._blocksPlayer(box)) continue;
445:       if (!this._circleOverlap(box, this.position.x, this.position.z, r)) continue;
446: 
447:       if (axis === 'x') {
448:         const center = (box.min.x + box.max.x) * 0.5;
449:         if (this.position.x > center) this.position.x = box.max.x + r + 0.001;
450:         else this.position.x = box.min.x - r - 0.001;
451:         this.velocity.x = 0;
452:       } else {
453:         const center = (box.min.z + box.max.z) * 0.5;
454:         if (this.position.z > center) this.position.z = box.max.z + r + 0.001;
455:         else this.position.z = box.min.z - r - 0.001;
456:         this.velocity.z = 0;
457:       }
458:       this._wallHit = box;
459:     }
460:   }
461: 
462:   _blocksPlayer(box) {
463:     return box.max.y > this.position.y + C.player.stepHeight + 0.015 &&
464:       box.min.y < this.position.y + this.height - 0.018;
465:   }
466: 
467:   _circleOverlap(box, x, z, r) {
468:     const cx = clamp(x, box.min.x, box.max.x);
469:     const cz = clamp(z, box.min.z, box.max.z);
470:     const dx = x - cx, dz = z - cz;
471:     return dx * dx + dz * dz < r * r;
472:   }
473: 
474:   _groundHeight(x, z, maxY) {
475:     let best = 0; // world floor
476:     for (const { box } of this.world.colliders) {
477:       if (!this._circleOverlap(box, x, z, this.radius * 0.72)) continue;
478:       const top = box.max.y;
479:       if (top <= maxY + 0.001 && top > best) best = top;
480:     }
481:     return best;
482:   }
483: 
484:   _canStand() {
485:     const target = this.position.y + this.standingHeight - 0.02;
486:     for (const { box } of this.world.colliders) {
487:       if (box.min.y >= target) continue;
488:       if (box.max.y <= this.position.y + C.player.stepHeight) continue;
489:       if (this._circleOverlap(box, this.position.x, this.position.z, this.radius * 0.8)) return false;
490:     }
491:     return true;
492:   }
493: 
494:   // ── Mantling ────────────────────────────────────────────────────────────────
495:   _tryMantle(input, fromJump) {
496:     if (this.mantleCooldown > 0 || this.mantling) return false;
497:     if (!fromJump && this.airTime < 0.04) return false;
498:     const ledge = this._findLedge();
499:     if (!ledge) return false;
500: 
501:     const speed = Math.hypot(this.velocity.x, this.velocity.z);
502:     this._mantle = {
503:       t: 0,
504:       duration: C.mantle.duration,
505:       start: this.position.clone(),
506:       end: new THREE.Vector3(ledge.x, ledge.top + 0.01, ledge.z),
507:       speed,
508:       dirX: ledge.dirX,
509:       dirZ: ledge.dirZ,
510:     };
511:     this.mantling = true;
512:     this.grounded = false;
513:     this.sliding = false;
514:     this.crouching = false;
515:     this.height = this.standingHeight;
516:     this.velocity.set(0, 0, 0);
517:     this.mantleCooldown = C.mantle.cooldown;
518:     this.emit('mantle', ledge.top);
519:     return true;
520:   }
521: 
522:   _findLedge() {
523:     const f = this.forward;
524:     const feet = this.position.y;
525:     let best = null;
526:     let bestTop = -Infinity;
527: 
528:     for (const dist of [0.68, 1.0, 1.22]) {
529:       const px = this.position.x + f.x * dist;
530:       const pz = this.position.z + f.z * dist;
531:       for (const { box } of this.world.colliders) {
532:         const top = box.max.y;
533:         if (top < feet + C.mantle.minHeight || top > feet + C.mantle.maxHeight) continue;
534:         if (px < box.min.x - 0.08 || px > box.max.x + 0.08 || pz < box.min.z - 0.08 || pz > box.max.z + 0.08) continue;
535:         if (top <= bestTop) continue;
536:         if (!this._hasHeadroom(top, px, pz)) continue;
537:         bestTop = top;
538:         best = {
539:           top,
540:           x: this.position.x + f.x * (dist + 0.36),
541:           z: this.position.z + f.z * (dist + 0.36),
542:           dirX: f.x,
543:           dirZ: f.z,
544:         };
545:       }
546:     }
547:     return best;
548:   }
549: 
550:   _hasHeadroom(top, x, z) {
551:     const head = top + this.standingHeight - 0.05;
552:     for (const { box } of this.world.colliders) {
553:       if (box.max.y <= top + 0.05 || box.min.y >= head) continue;
554:       if (x > box.min.x - this.radius * 0.7 && x < box.max.x + this.radius * 0.7 &&
555:           z > box.min.z - this.radius * 0.7 && z < box.max.z + this.radius * 0.7) return false;
556:     }
557:     return true;
558:   }
559: 
560:   _updateMantle(dt) {
561:     const m = this._mantle;
562:     if (!m) { this.mantling = false; return; }
563:     m.t += dt;
564:     const t = clamp(m.t / m.duration, 0, 1);
565: 
566:     // Up first, then over the lip. Reads as a fast arcade pull-up.
567:     const up = easeOutCubic(Math.min(1, t / 0.68));
568:     const over = easeInOutCubic(clamp((t - 0.22) / 0.78, 0, 1));
569:     this.position.y = m.start.y + (m.end.y - m.start.y) * up;
570:     this.position.x = m.start.x + (m.end.x - m.start.x) * over;
571:     this.position.z = m.start.z + (m.end.z - m.start.z) * over;
572:     this.eyeTarget = C.player.eyeStanding - 0.15 + Math.sin(t * Math.PI) * 0.1;
573: 
574:     if (t >= 1) {
575:       this.position.copy(m.end);
576:       this.grounded = true;
577:       this.mantling = false;
578:       this._mantle = null;
579:       const exitSpeed = Math.max(3.2, Math.min(C.movement.sprintSpeed, m.speed * 0.94));
580:       this.velocity.set(m.dirX * exitSpeed, 0, m.dirZ * exitSpeed);
581:       this.mantleCooldown = C.mantle.cooldown;
582:       this.emit('mantleEnd');
583:     }
