import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime = `${process.env.HOME}/.local/share/omgithub-playwright`;
const require = createRequire(`${runtime}/package.json`);
const { chromium } = require('playwright');
process.env.DISPLAY ||= ':' + readFileSync(`${runtime}/display`, 'utf8').trim();
const config = JSON.parse(readFileSync(`${runtime}/linux.json`, 'utf8'));
const out = '/home/runner/work/PlayGround/PlayGround/screenshots';
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
page.on('pageerror', e => console.log('[pageerror]', e.message));
await page.goto('http://localhost:3000', { waitUntil: 'load' });
await page.waitForFunction(() => document.fonts.status === 'loaded');
await page.getByRole('button', { name: /^start$/i }).click();
await page.waitForTimeout(900);
const info = await page.evaluate(() => {
  const g = window.COMBAT_SHIFT.game;
  const list = [];
  g.weapon.recoilGroup.children.forEach((o, i) => {
    if (!o.isMesh) return;
    const b = new o.geometry.boundingBox?.constructor?.();
    o.geometry.computeBoundingBox();
    const bb = o.geometry.boundingBox;
    list.push({ i, type: o.material.type, hex: o.material.color?.getHexString(), metal: o.material.metalness, rough: o.material.roughness, min: bb.min.toArray().map(v=>+v.toFixed(2)), max: bb.max.toArray().map(v=>+v.toFixed(2)), tris: o.geometry.attributes.position.count/3 });
  });
  return list;
});
console.log(info);
// All materials black, no metalness, no lights.
await page.evaluate(() => {
  const g = window.COMBAT_SHIFT.game;
  g.camera.children.filter(o => o.isLight).forEach(l => l.intensity = 0);
  g.weapon.recoilGroup.traverse(o => {
    if (!o.isMesh) return;
    if (o.material.isMeshStandardMaterial) {
      o.material.color.setHex(0x000000);
      o.material.emissive.setHex(0x000000);
      o.material.metalness = 0;
      o.material.roughness = 1;
      o.material.needsUpdate = true;
    } else if (o.material.isMeshBasicMaterial) {
      o.material.color.setHex(0x000000);
    }
  });
});
await page.waitForTimeout(300);
await page.screenshot({ path: `${out}/gun-black.jpg`, type: 'jpeg', quality: 82 });
// Assign each material mesh a distinct test color, no lights, metalness 0.
await page.evaluate(() => {
  const g = window.COMBAT_SHIFT.game;
  const colors = [0xff0000, 0x00ff00, 0x0000ff, 0xffff00, 0xff00ff, 0x00ffff, 0xffffff, 0x804000, 0x008040, 0x800080, 0x404040];
  let i = 0;
  g.weapon.recoilGroup.traverse(o => {
    if (!o.isMesh) return;
    const c = colors[i++ % colors.length];
    o.material = new o.material.constructor({ color: c, metalness: 0, roughness: .8 });
    if (o.material.isMeshBasicMaterial) o.material = new o.material.constructor({ color: c });
  });
});
await page.waitForTimeout(300);
await page.screenshot({ path: `${out}/gun-debug.jpg`, type: 'jpeg', quality: 82 });
await browser.close();

