  window.dispatchEvent(new KeyboardEvent(d ? 'keydown' : 'keyup', { code: c, bubbles: true }));
}, [code, down]);
const aimAt = (targetIndex, yOffset = 0) => page.evaluate(([i, yo]) => {
  const g = window.COMBAT_SHIFT.game;
  const t = g.combat.targets[i];
  const p = t.root.position;
  const px = g.player.position.x, pz = g.player.position.z;
  const dx = p.x - px, dz = p.z - pz;
  const dist = Math.hypot(dx, dz);
  g.player.yaw = Math.atan2(-dx, -dz);
  g.player.pitch = Math.atan2((p.y + 1.3 + yo) - (g.player.position.y + g.player.eyeHeight), dist);
}, [targetIndex, yOffset]);
const sleep = ms => new Promise(r => setTimeout(r, ms));
