import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime = `${process.env.HOME}/.local/share/omgithub-playwright`;
const require = createRequire(`${runtime}/package.json`);
const { chromium } = require('playwright');
process.env.DISPLAY ||= ':' + readFileSync(`${runtime}/display`, 'utf8').trim();
const config = JSON.parse(readFileSync(`${runtime}/linux.json`, 'utf8'));
const out = '/home/runner/work/PlayGround/PlayGround/screenshots';
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
const errors = [];
page.on('pageerror', e => { console.log('[pageerror]', e.message); errors.push(e.message); });
page.on('console', m => { if (m.type() === 'error') { console.log('[consoleerror]', m.text()); errors.push(m.text()); } });
await page.goto('http://localhost:3000', { waitUntil: 'load' });
await page.waitForFunction(() => document.fonts.status === 'loaded');
await page.getByRole('button', { name: /^start$/i }).click();
await page.waitForTimeout(700);
const sleep = ms => new Promise(r => setTimeout(r, ms));
const state = () => page.evaluate(() => window.COMBAT_SHIFT.state);
const key = (code, down) => page.evaluate(([c, d]) => window.dispatchEvent(new KeyboardEvent(d ? 'keydown' : 'keyup', { code: c, bubbles: true })), [code, down]);
const aimAt = (i) => page.evaluate((idx) => {
  const g = window.COMBAT_SHIFT.game; const t = g.combat.targets[idx]; const p = t.root.position;
  const dx = p.x - g.player.position.x, dz = p.z - g.player.position.z;
  g.player.yaw = Math.atan2(-dx, -dz);
  g.player.pitch = Math.atan2((p.y + 1.25) - (g.player.position.y + g.player.eyeHeight), Math.hypot(dx, dz));
}, i);
const aimHead = (i) => page.evaluate((idx) => {
  const g = window.COMBAT_SHIFT.game; const t = g.combat.targets[idx]; const p = t.root.position;
  const dx = p.x - g.player.position.x, dz = p.z - g.player.position.z;
  g.player.yaw = Math.atan2(-dx, -dz);
  g.player.pitch = Math.atan2((p.y + 1.8) - (g.player.position.y + g.player.eyeHeight), Math.hypot(dx, dz));
}, i);

console.log('\n=== COMBAT ===');
await page.evaluate(() => { const g=window.COMBAT_SHIFT.game; g.player.position.set(-1.5,0,19); g.player.velocity.set(0,0,0); g.player.grounded=true; });
await sleep(250);
for (let i=0;i<3;i++) {
  await aimAt(0);
  await page.evaluate(() => window.COMBAT_SHIFT.fire(80));
  if (i===0) { await page.screenshot({ path: `${out}/check-shot.jpg`, type: 'jpeg', quality: 82 }); }
  await sleep(220);
  const snapshot = await page.evaluate(() => ({
    ...window.COMBAT_SHIFT.state,
    hp: window.COMBAT_SHIFT.game.combat.targets[0].hp,
    down: window.COMBAT_SHIFT.game.combat.targets[0].down,
    scoreText: document.getElementById('score').textContent,
    targetsText: document.getElementById('targetCount').textContent,
    ammoText: document.getElementById('ammo').textContent,
    label: document.getElementById('reloadLabel').textContent,
  }));
  console.log(`shot ${i+1}`, { ammo: snapshot.ammo, hp: snapshot.hp, down: snapshot.down, score: snapshot.scoreText, kills: snapshot.targetsText, ammoText: snapshot.ammoText, reload: snapshot.label });
}
await page.screenshot({ path: `${out}/check-kill.jpg`, type: 'jpeg', quality: 82 });
console.log('HUD after kill', await page.evaluate(() => ({
  score: document.getElementById('score').textContent,
  targets: document.getElementById('targetCount').textContent,
  ammo: document.getElementById('ammo').textContent,
  feed: [...document.querySelectorAll('#eventFeed .event')].map(e => e.textContent),
  toast: document.getElementById('toast').textContent,
})));

// Headshot another target from close range.
await page.evaluate(() => { const g=window.COMBAT_SHIFT.game; g.player.position.set(-10.8,0,-9.5); g.player.velocity.set(0,0,0); g.player.grounded=true; });
await sleep(250);
await aimHead(2);
await page.evaluate(() => window.COMBAT_SHIFT.fire(80));
await sleep(250);
console.log('headshot', await page.evaluate(() => ({ score: window.COMBAT_SHIFT.game.combat.score, kills: window.COMBAT_SHIFT.game.combat.kills, hp: window.COMBAT_SHIFT.game.combat.targets[2].hp, down: window.COMBAT_SHIFT.game.combat.targets[2].down })));

// Reload flow with one bullet.
console.log('\n=== RELOAD ===');
await page.evaluate(() => { const g=window.COMBAT_SHIFT.game; g.combat.ammo=1; g.combat.cooldown=0; g.combat.reloading=false; g.weapon.finishReload(); });
await aimAt(2);
await page.evaluate(() => window.COMBAT_SHIFT.fire(60));
await sleep(250);
console.log('reload start', await page.evaluate(() => ({ ammo: window.COMBAT_SHIFT.game.combat.ammo, reloading: window.COMBAT_SHIFT.game.combat.reloading, label: document.getElementById('reloadLabel').textContent })));
await sleep(1700);
console.log('reload end', await page.evaluate(() => ({ ammo: window.COMBAT_SHIFT.game.combat.ammo, reloading: window.COMBAT_SHIFT.game.combat.reloading, label: document.getElementById('reloadLabel').textContent })));

// ── Sprint → auto-bhop ───────────────────────────────────────────────────────
console.log('\n=== BHOP ===');
await page.evaluate(() => { window.COMBAT_SHIFT.teleport(0, 19); window.COMBAT_SHIFT.look(0, 0); });
await sleep(250);
await key('KeyW', true); await key('ShiftLeft', true);
await sleep(1300);
const preBhop = await state();
await key('Space', true);
const bhop = [];
for (let i=0;i<26;i++) { await sleep(100); bhop.push(await page.evaluate(() => { const s=window.COMBAT_SHIFT.state; return {y:+s.position[1].toFixed(2), sp:+s.speed.toFixed(1), g:s.grounded, a:s.airborne}; })); }
await key('Space', false); await key('ShiftLeft', false); await key('KeyW', false);
await sleep(200);
const bhopResult = await state();
console.log('preBhop', { speed: preBhop.speed, sprinting: preBhop.sprinting });
console.log('bhop trace', bhop.map(s=>`${s.y}/${s.sp}${s.a?'a':'g'}`).join(' '));
console.log('bhop summary', {
  maxSpeed: Math.max(...bhop.map(s=>s.sp)),
  airFrames: bhop.filter(s=>s.a).length,
  landings: bhop.reduce((n,s,i)=>n+(i>0 && s.g && bhop[i-1].a?1:0),0),
  minSpeed: Math.min(...bhop.map(s=>s.sp)),
  end: { speed: bhopResult.speed, position: bhopResult.position },
});

// ── Clean mantle onto 1.9m platform from clear left side ────────────────────
console.log('\n=== MANTLE ===');
await page.evaluate(() => { window.COMBAT_SHIFT.teleport(-19.5, -6.4); window.COMBAT_SHIFT.look(0, 0); });
await sleep(250);
await key('KeyW', true); await key('ShiftLeft', true);
await sleep(100);
await key('Space', true);
const mantle = [];
for (let i=0;i<24;i++) { await sleep(60); mantle.push(await page.evaluate(() => { const s=window.COMBAT_SHIFT.state; return {x:+s.position[0].toFixed(2),y:+s.position[1].toFixed(2),z:+s.position[2].toFixed(2),m:s.mantling,g:s.grounded}; })); }
await key('Space', false); await key('ShiftLeft', false); await key('KeyW', false);
await sleep(250);
const mantleEnd = await state();
console.log('mantle trace', mantle.map(s=>`${s.z}/${s.y}${s.m?'M':s.g?'g':'a'}`).join(' '));
console.log('mantle result', { sawMantle: mantle.some(s=>s.m), end: { pos: mantleEnd.position, grounded: mantleEnd.grounded, speed: mantleEnd.speed } });
await page.screenshot({ path: `${out}/check-mantle2.jpg`, type: 'jpeg', quality: 82 });

console.log('\nerrors', errors);
await browser.close();

