import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime = `${process.env.HOME}/.local/share/omgithub-playwright`;
const require = createRequire(`${runtime}/package.json`);
const { chromium } = require('playwright');
process.env.DISPLAY ||= ':' + readFileSync(`${runtime}/display`, 'utf8').trim();
const config = JSON.parse(readFileSync(`${runtime}/linux.json`, 'utf8'));
const out = '/home/runner/work/PlayGround/PlayGround/screenshots';
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const errors = [];
async function makePage(width, height, name) {
  const page = await browser.newPage({ viewport: { width, height } });
  page.on('pageerror', e => { console.log(`[${name} pageerror]`, e.message); errors.push(`${name}: ${e.message}`); });
  page.on('console', m => { if (m.type() === 'error') { console.log(`[${name} consoleerror]`, m.text()); errors.push(`${name}: ${m.text()}`); } });
  page.on('response', r => { if (r.status() >= 400) { console.log(`[${name} http]`, r.status(), r.url()); errors.push(`${name}: HTTP ${r.status()}`); } });
  await page.goto('http://localhost:3000', { waitUntil: 'load' });
  await page.waitForFunction(() => document.fonts.status === 'loaded');
  await page.waitForTimeout(700);
  return page;
}

const desk = await makePage(1280, 720, 'desktop');
await desk.screenshot({ path: `${out}/audit-menu-desktop.jpg`, type: 'jpeg', quality: 84 });
console.log('desktop menu overflow', await desk.evaluate(() => ({ sw: document.documentElement.scrollWidth, sh: document.documentElement.scrollHeight, iw: innerWidth, ih: innerHeight })));
await desk.getByRole('button', { name: /^start$/i }).click();
await desk.waitForTimeout(1200);
await desk.screenshot({ path: `${out}/audit-play-desktop.jpg`, type: 'jpeg', quality: 84 });
console.log('desktop gameplay', await desk.evaluate(() => {
  const g = window.COMBAT_SHIFT.game;
  return { state: window.COMBAT_SHIFT.state, isTouch: g.input.touch, draw: g.renderer.info.render, pixelRatio: g.renderer.getPixelRatio(), software: g.softwareRenderer, hudHidden: document.getElementById('hud').classList.contains('is-hidden'), targetsTotal: document.querySelector('.drill-sub').textContent.trim() };
}));
// quick tap firing check
await desk.evaluate(() => window.COMBAT_SHIFT.fire(1));
await desk.waitForTimeout(350);
console.log('quick tap ammo', await desk.evaluate(() => ({ ammo: window.COMBAT_SHIFT.game.combat.ammo, shots: window.COMBAT_SHIFT.game.combat.shots })));
// target respawn
console.log('respawn before/after', await desk.evaluate(() => ({ down: window.COMBAT_SHIFT.game.combat.targets[0].down, hp: window.COMBAT_SHIFT.game.combat.targets[0].hp })));
await desk.waitForTimeout(3300);
console.log('respawn after', await desk.evaluate(() => ({ down: window.COMBAT_SHIFT.game.combat.targets[0].down, hp: window.COMBAT_SHIFT.game.combat.targets[0].hp })));

const mob = await makePage(390, 844, 'mobile');
await mob.screenshot({ path: `${out}/audit-menu-mobile.jpg`, type: 'jpeg', quality: 84 });
console.log('mobile menu overflow', await mob.evaluate(() => ({ sw: document.documentElement.scrollWidth, sh: document.documentElement.scrollHeight, iw: innerWidth, ih: innerHeight })));
await mob.getByRole('button', { name: /^start$/i }).click();
await mob.waitForTimeout(1200);
await mob.screenshot({ path: `${out}/audit-play-mobile.jpg`, type: 'jpeg', quality: 84 });
console.log('mobile gameplay', await mob.evaluate(() => {
  const g = window.COMBAT_SHIFT.game;
  const rect = (sel) => { const el = document.querySelector(sel); if (!el) return null; const r = el.getBoundingClientRect(); return { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) }; };
  return {
    isTouch: g.input.touch, hudHidden: document.getElementById('hud').classList.contains('is-hidden'), touchHidden: document.getElementById('touchControls').classList.contains('is-hidden'),
    momentum: rect('.momentum'), weapon: rect('.weapon'), stick: rect('.stick-base'), actions: rect('.touch-actions'), fire: rect('#touchFire'), startButton: rect('#startButton'),
    overflow: { sw: document.documentElement.scrollWidth, sh: document.documentElement.scrollHeight },
    draw: g.renderer.info.render,
  };
}));
console.log('errors', errors);
await browser.close();

