import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime = `${process.env.HOME}/.local/share/omgithub-playwright`;
const require = createRequire(`${runtime}/package.json`);
const { chromium } = require('playwright');
process.env.DISPLAY ||= ':' + readFileSync(`${runtime}/display`, 'utf8').trim();
const config = JSON.parse(readFileSync(`${runtime}/linux.json`, 'utf8'));
const out = '/home/runner/work/PlayGround/PlayGround/screenshots';
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const errors = [];
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
page.on('pageerror', e => { console.log('[pageerror]', e.message); errors.push(e.message); });
page.on('console', m => { if (m.type() === 'error') { console.log('[consoleerror]', m.text()); errors.push(m.text()); } });
page.on('response', r => { if (r.status() >= 400) { console.log('[http]', r.status(), r.url()); errors.push(`HTTP ${r.status()}`); } });
await page.goto('http://localhost:3000', { waitUntil: 'load' });
await page.waitForFunction(() => document.fonts.status === 'loaded');
await page.waitForTimeout(600);
await page.screenshot({ path: `${out}/final-menu.jpg`, type: 'jpeg', quality: 84 });
await page.getByRole('button', { name: /^start$/i }).click();
await page.waitForTimeout(1000);

// Quick-click: one render frame and one catch-up burst must produce one bullet.
await page.evaluate(() => window.COMBAT_SHIFT.fire(1));
await page.waitForTimeout(400);
console.log('quick tap', await page.evaluate(() => ({ ammo: window.COMBAT_SHIFT.game.combat.ammo, shots: window.COMBAT_SHIFT.game.combat.shots })));

// Focus on target dummy 0 and capture a burst while it is still standing.
await page.evaluate(() => {
  const g = window.COMBAT_SHIFT.game;
  g.player.position.set(-1.5, 0, 17.5); g.player.velocity.set(0,0,0); g.player.grounded = true;
});
await page.waitForTimeout(300);
const aim = () => page.evaluate(() => {
  const g = window.COMBAT_SHIFT.game; const p = g.combat.targets[0].root.position;
  const dx = p.x - g.player.position.x, dz = p.z - g.player.position.z;
  g.player.yaw = Math.atan2(-dx, -dz);
  g.player.pitch = Math.atan2((p.y + 1.35) - (g.player.position.y + g.player.eyeHeight), Math.hypot(dx, dz));
});
await aim();
await page.evaluate(() => window.COMBAT_SHIFT.fire(55));
await page.waitForTimeout(160);
await page.screenshot({ path: `${out}/final-action.jpg`, type: 'jpeg', quality: 84 });
await page.waitForTimeout(320);
console.log('burst state', await page.evaluate(() => ({ score: window.COMBAT_SHIFT.game.combat.score, kills: window.COMBAT_SHIFT.game.combat.kills, ammo: window.COMBAT_SHIFT.game.combat.ammo, targetDown: window.COMBAT_SHIFT.game.combat.targets[0].down })));

// Verify automatic reload reaches full ammo.
await page.evaluate(() => { const g=window.COMBAT_SHIFT.game; g.combat.ammo=1; g.combat.cooldown=0; g.combat.reloading=false; g.weapon.finishReload(); });
await aim();
await page.evaluate(() => window.COMBAT_SHIFT.fire(1));
await page.waitForTimeout(300);
console.log('reload auto-start', await page.evaluate(() => ({ ammo: window.COMBAT_SHIFT.game.combat.ammo, reloading: window.COMBAT_SHIFT.game.combat.reloading })));
await page.waitForTimeout(3500);
console.log('reload complete', await page.evaluate(() => ({ ammo: window.COMBAT_SHIFT.game.combat.ammo, reloading: window.COMBAT_SHIFT.game.combat.reloading, label: document.getElementById('reloadLabel').textContent })));

// Force a kill on the first target and confirm the dummy comes back.
await page.evaluate(() => { const t = window.COMBAT_SHIFT.game.combat.targets[0]; t.down = false; t.hp = 100; t.hit(999, 'body'); });
await page.waitForTimeout(4500);
console.log('respawn', await page.evaluate(() => ({ down: window.COMBAT_SHIFT.game.combat.targets[0].down, hp: window.COMBAT_SHIFT.game.combat.targets[0].hp })));

// Framing + final screenshot from the spawn view.
await page.evaluate(() => { window.COMBAT_SHIFT.teleport(-1.5, 21.5); window.COMBAT_SHIFT.look(0, 0); });
await page.waitForTimeout(700);
await page.screenshot({ path: `${out}/final-desktop.jpg`, type: 'jpeg', quality: 84 });
// Centre crop to inspect reticle / route.
await page.screenshot({ path: `${out}/final-center-crop.jpg`, type: 'jpeg', quality: 88, clip: { x: 390, y: 220, width: 500, height: 360 } });

// Mobile layout after CSS changes.
const mob = await browser.newPage({ viewport: { width: 390, height: 844 } });
mob.on('pageerror', e => { console.log('[mobile pageerror]', e.message); errors.push(e.message); });
mob.on('console', m => { if (m.type() === 'error') { console.log('[mobile consoleerror]', m.text()); errors.push(m.text()); } });
await mob.goto('http://localhost:3000', { waitUntil: 'load' });
await mob.waitForFunction(() => document.fonts.status === 'loaded');
await mob.waitForTimeout(600);
await mob.screenshot({ path: `${out}/final-mobile-menu.jpg`, type: 'jpeg', quality: 84 });
await mob.getByRole('button', { name: /^start$/i }).click();
await mob.waitForTimeout(1100);
await mob.screenshot({ path: `${out}/final-mobile.jpg`, type: 'jpeg', quality: 84 });
console.log('mobile rects', await mob.evaluate(() => {
  const rect = (sel) => { const el = document.querySelector(sel); if (!el) return null; const r = el.getBoundingClientRect(); return { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) }; };
  return { momentum: rect('.momentum'), weapon: rect('.weapon'), stick: rect('.stick-base'), actions: rect('.touch-actions'), note: document.querySelector('.start-note')?.textContent, reloadLabel: document.getElementById('reloadLabel').textContent, isTouch: window.COMBAT_SHIFT.game.input.touch };
}));
console.log('errors', errors);
await browser.close();

