import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime = `${process.env.HOME}/.local/share/omgithub-playwright`;
const require = createRequire(`${runtime}/package.json`);
const { chromium } = require('playwright');
process.env.DISPLAY ||= ':' + readFileSync(`${runtime}/display`, 'utf8').trim();
const config = JSON.parse(readFileSync(`${runtime}/linux.json`, 'utf8'));
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 960, height: 540 } });
const errors = [];
page.on('pageerror', e => { console.log('[pageerror]', e.message); errors.push(e.message); });
await page.goto('http://localhost:3000', { waitUntil: 'load' });
await page.waitForFunction(() => document.fonts.status === 'loaded');
await page.getByRole('button', { name: /^start$/i }).click();
await page.waitForTimeout(600);
const key = (code, down) => page.evaluate(([c,d]) => window.dispatchEvent(new KeyboardEvent(d?'keydown':'keyup',{code:c,bubbles:true})), [code,down]);
const state = () => page.evaluate(() => window.COMBAT_SHIFT.state);

// Air strafe: jump forward, drop W and hold A. Speed should rise above sprint.
console.log('=== AIR STRAFE ===');
await page.evaluate(() => { window.COMBAT_SHIFT.teleport(0, 20); window.COMBAT_SHIFT.look(0, 0); });
await page.waitForTimeout(200);
await key('KeyW', true); await key('ShiftLeft', true);
await page.waitForTimeout(1300);
const before = await state();
await key('Space', true);
await page.waitForTimeout(100);
await key('KeyW', false); await key('Space', false); await key('KeyA', true);
const air = [];
for (let i=0;i<16;i++) { await page.waitForTimeout(70); air.push(await page.evaluate(() => { const s=window.COMBAT_SHIFT.state; return { sp:+s.speed.toFixed(2), y:+s.position[1].toFixed(2), a:s.airborne, vx:+s.velocity[0].toFixed(2), vz:+s.velocity[2].toFixed(2) }; })); }
await key('KeyA', false); await key('ShiftLeft', false);
console.log('before', { speed: before.speed, vel: before.velocity });
console.log('air', air.map(s=>`${s.sp}/${s.y}${s.a?'a':'g'}`).join(' '));
console.log('air result', { maxSpeed: Math.max(...air.map(s=>s.sp)), base: before.speed, finalVel: air[air.length-1] });
await page.waitForTimeout(300);

// Touch controls.
console.log('\n=== TOUCH ===');
const mob = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true });
mob.on('pageerror', e => { console.log('[mobile pageerror]', e.message); errors.push(e.message); });
await mob.goto('http://localhost:3000', { waitUntil: 'load' });
await mob.waitForFunction(() => document.fonts.status === 'loaded');
await mob.getByRole('button', { name: /^start$/i }).tap();
await mob.waitForTimeout(800);
const rightThumb = await mob.evaluate(() => {
  const a = document.querySelector('.touch-actions').getBoundingClientRect();
  const left = document.querySelector('.stick-base').getBoundingClientRect();
  return { ax:a.x, ay:a.y, aw:a.width, ah:a.height, lx:left.x, ly:left.y, lw:left.width, lh:left.height };
});
// Tap fire.
const ammo0 = await mob.evaluate(() => window.COMBAT_SHIFT.game.combat.ammo);
await mob.locator('#touchFire').tap();
await mob.waitForTimeout(500);
const ammo1 = await mob.evaluate(() => window.COMBAT_SHIFT.game.combat.ammo);
console.log('touch fire ammo', { before: ammo0, after: ammo1 });
// Jump.
const y0 = await mob.evaluate(() => window.COMBAT_SHIFT.state.position[1]);
await mob.locator('#touchJump').tap();
await mob.waitForTimeout(250);
const jumpState = await mob.evaluate(() => ({ y: window.COMBAT_SHIFT.state.position[1], airborne: window.COMBAT_SHIFT.state.airborne }));
console.log('touch jump', { y0, ...jumpState });
await mob.waitForTimeout(900);
// Stick drag upward -> forward speed.
const sx = rightThumb.lx + rightThumb.lw/2, sy = rightThumb.ly + rightThumb.lh/2;
await mob.mouse.move(sx, sy);
await mob.mouse.down();
await mob.mouse.move(sx, sy - 48, { steps: 4 });
await mob.waitForTimeout(700);
const stickState = await mob.evaluate(() => ({ stick: { ...window.COMBAT_SHIFT.game.input.stick }, speed: window.COMBAT_SHIFT.state.speed, position: window.COMBAT_SHIFT.state.position }));
await mob.mouse.up();
await mob.waitForTimeout(200);
console.log('touch stick', { stick: stickState.stick, speed: +stickState.speed.toFixed(2), z: +stickState.position[2].toFixed(2) });
// Look drag on canvas.
const yaw0 = await mob.evaluate(() => window.COMBAT_SHIFT.state.yaw);
await mob.mouse.move(195, 380);
await mob.mouse.down();
await mob.mouse.move(260, 380, { steps: 4 });
await mob.mouse.up();
await mob.waitForTimeout(300);
const yaw1 = await mob.evaluate(() => window.COMBAT_SHIFT.state.yaw);
console.log('touch look yaw', { yaw0, yaw1 });
console.log('errors', errors);
await browser.close();

