import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime = `${process.env.HOME}/.local/share/omgithub-playwright`;
const require = createRequire(`${runtime}/package.json`);
const { chromium } = require('playwright');
process.env.DISPLAY ||= ':' + readFileSync(`${runtime}/display`, 'utf8').trim();
const config = JSON.parse(readFileSync(`${runtime}/linux.json`, 'utf8'));
const out = '/home/runner/work/PlayGround/PlayGround/screenshots';
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const errors = [];
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
page.on('pageerror', e => { console.log('[pageerror]', e.message); errors.push(e.message); });
page.on('console', m => { if (m.type() === 'error') { console.log('[consoleerror]', m.text()); errors.push(m.text()); } });
page.on('response', r => { if (r.status() >= 400) { console.log('[http]', r.status(), r.url()); errors.push(`HTTP ${r.status()}`); } });
await page.goto('http://localhost:3000', { waitUntil: 'load' });
await page.waitForFunction(() => document.fonts.status === 'loaded');
await page.waitForTimeout(700);
await page.getByRole('button', { name: /^start$/i }).click();
await page.waitForTimeout(1000);
// Slide frame.
await page.evaluate(() => { window.COMBAT_SHIFT.teleport(-1.5, 21.5); window.COMBAT_SHIFT.look(0, 0); });
const key = (c,d) => page.evaluate(([c,d]) => window.dispatchEvent(new KeyboardEvent(d?'keydown':'keyup',{code:c,bubbles:true})), [c,d]);
await key('KeyW', true); await key('ShiftLeft', true);
await page.waitForTimeout(1400);
await key('ControlLeft', true);
await page.waitForTimeout(450);
await page.screenshot({ path: `${out}/final-slide.jpg`, type: 'jpeg', quality: 84 });
console.log('slide', await page.evaluate(() => ({ speed: window.COMBAT_SHIFT.game.player.horizontalSpeed, sliding: window.COMBAT_SHIFT.game.player.sliding, fov: window.COMBAT_SHIFT.game.camera.fov })));
await key('ControlLeft', false); await key('ShiftLeft', false); await key('KeyW', false);
await page.waitForTimeout(300);

// Mobile responsive view model + layout.
const mob = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true });
mob.on('pageerror', e => { console.log('[mobile pageerror]', e.message); errors.push(e.message); });
mob.on('console', m => { if (m.type() === 'error') { console.log('[mobile consoleerror]', m.text()); errors.push(m.text()); } });
await mob.goto('http://localhost:3000', { waitUntil: 'load' });
await mob.waitForFunction(() => document.fonts.status === 'loaded');
await mob.waitForTimeout(700);
await mob.getByRole('button', { name: /^start$/i }).tap();
await mob.waitForTimeout(1100);
await mob.screenshot({ path: `${out}/final-mobile.jpg`, type: 'jpeg', quality: 86 });
console.log('mobile', await mob.evaluate(() => {
  const g = window.COMBAT_SHIFT.game, w = g.weapon;
  const rect = (sel) => { const el=document.querySelector(sel); if(!el) return null; const r=el.getBoundingClientRect(); return { x:Math.round(r.x),y:Math.round(r.y),w:Math.round(r.width),h:Math.round(r.height) }; };
  return {
    aspect: +g.camera.aspect.toFixed(3), weaponBase: w.base.toArray().map(v=>+v.toFixed(2)), weaponX: +w.root.position.x.toFixed(2), weaponScale: +w.root.scale.x.toFixed(2),
    momentum: rect('.momentum'), weaponPanel: rect('.weapon'), stick: rect('.stick-base'), actions: rect('.touch-actions'),
    targetTotal: document.querySelector('.drill-sub').textContent.trim(), drillLabel: getComputedStyle(document.querySelector('.drill-label')).display,
    label: document.getElementById('reloadLabel').textContent, draw: g.renderer.info.render, errors: [],
  };
}));
console.log('errors', errors);
await browser.close();

